export const questions: Question[] = [
  { id: "y2fg6-001", topicRef: "y2fg6", topicTitle: "Combining Transformations 01", difficulty: "Challenge", questionText: "The curve \\( y = f(x) \\) has a single maximum point at \\((4, -2)\\). The curve is mapped onto \\( y = 3f(2x - 6) + 5 \\). (a) Express \\( 2x - 6 \\) in the form \\( 2(x - a) \\) and hence list the four transformations in the order they must be applied. (b) Determine the coordinates of the image of the maximum point, stating whether it remains a maximum.", marks: 7, examStyle: true, yearCreated: 2026, tags: ["transformations", "order", "composite-argument", "image"], workedSolution: { steps: [ { stepNumber: 1, description: "Factorise the argument so the inside transformations are visible.", workingLatex: "2x - 6 = 2(x - 3)", explanation: "You must factor out the coefficient of \\(x\\) before reading the horizontal shift; the shift is \\(3\\), not \\(6\\). This is the single most common slip." }, { stepNumber: 2, description: "List the inside (horizontal) transformations, innermost first.", workingLatex: "x \\mapsto x - 3 \\ \\text{then} \\ x \\mapsto 2x", explanation: "Inside the bracket, replacing \\(x\\) by \\(x-3\\) is a translation right \\(3\\); replacing \\(x\\) by \\(2x\\) is a horizontal stretch of scale factor \\(\\tfrac{1}{2}\\). Horizontal transformations act in the opposite sense to intuition." }, { stepNumber: 3, description: "List the outside (vertical) transformations.", workingLatex: "y \\mapsto 3y \\ \\text{then} \\ y \\mapsto y + 5", explanation: "Outside the function, multiplying by \\(3\\) is a vertical stretch scale factor \\(3\\), then adding \\(5\\) is a translation up \\(5\\). Outside transformations behave intuitively." }, { stepNumber: 4, description: "Track the maximum through the horizontal steps.", workingLatex: "(4, -2) \\xrightarrow{\\text{right }3} (7, -2) \\xrightarrow{\\text{stretch} \\times \\tfrac12} (\\tfrac{7}{2}, -2)", explanation: "Translate right \\(3\\): add \\(3\\) to the \\(x\\)-coordinate. Then a horizontal stretch factor \\(\\tfrac12\\) halves the \\(x\\)-coordinate. The \\(y\\)-coordinate is untouched by horizontal moves." }, { stepNumber: 5, description: "Track the point through the vertical steps.", workingLatex: "(\\tfrac{7}{2}, -2) \\xrightarrow{\\times 3} (\\tfrac{7}{2}, -6) \\xrightarrow{+5} (\\tfrac{7}{2}, -1)", explanation: "Vertical stretch \\(\\times 3\\): multiply the \\(y\\)-coordinate by \\(3\\). Then add \\(5\\). A positive stretch does not flip the curve, so a maximum stays a maximum." } ], finalAnswer: "(a) \\(2x-6 = 2(x-3)\\); order: translate right \\(3\\), horizontal stretch scale factor \\(\\tfrac12\\), vertical stretch scale factor \\(3\\), translate up \\(5\\). (b) Image is \\((\\tfrac{7}{2}, -1)\\), still a maximum." } },
  // ── Describe transformation ────
  { id: "y2fg6-002", topicRef: "y2fg6", topicTitle: "Combining Transformations 02", difficulty: "Foundation", questionText: "Describe the transformation from \\(y = f(x)\\) to \\(y = f(x) + 5\\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Outside add.", workingLatex: "", explanation: "" } ], finalAnswer: "Translation up 5 (by \\(\\binom{0}{5}\\))." } },
  { id: "y2fg6-003", topicRef: "y2fg6", topicTitle: "Combining Transformations 03", difficulty: "Foundation", questionText: "Describe the transformation from \\(y = f(x)\\) to \\(y = f(x - 2)\\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Inside minus.", workingLatex: "", explanation: "" } ], finalAnswer: "Translation right 2 (by \\(\\binom{2}{0}\\))." } },
  { id: "y2fg6-004", topicRef: "y2fg6", topicTitle: "Combining Transformations 04", difficulty: "Foundation", questionText: "Describe the transformation from \\(y = f(x)\\) to \\(y = 3f(x)\\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Outside multiply.", workingLatex: "", explanation: "" } ], finalAnswer: "Vertical stretch, scale factor 3." } },
  { id: "y2fg6-005", topicRef: "y2fg6", topicTitle: "Combining Transformations 05", difficulty: "Challenge", questionText: "A function \\( g \\) is obtained from \\( f \\) by the rule \\( g(x) = f\\!\\left(\\tfrac{1}{2}x + 4\\right) \\). It is found that \\( g \\) has a root at \\( x = -2 \\) and a root at \\( x = 6 \\). (a) Write \\( \\tfrac{1}{2}x + 4 \\) in the form \\( \\tfrac{1}{2}(x + b) \\) and describe the transformation from \\( y = f(x) \\) to \\( y = g(x) \\) as an ordered sequence. (b) Hence find the \\( x \\)-coordinates of the corresponding roots of \\( y = f(x) \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["transformations", "order", "composite-argument", "find-original"], workedSolution: { steps: [ { stepNumber: 1, description: "Factorise the argument.", workingLatex: "\\tfrac{1}{2}x + 4 = \\tfrac{1}{2}(x + 8)", explanation: "Take out the coefficient of \\(x\\): \\(\\tfrac12 \\times 8 = 4\\), so \\(b = 8\\). Forgetting to factor would wrongly suggest a shift of \\(4\\)." }, { stepNumber: 2, description: "Describe the ordered sequence from \\(f\\) to \\(g\\).", workingLatex: "x \\mapsto x + 8 \\ \\text{then} \\ x \\mapsto \\tfrac12 x", explanation: "Inside the bracket, \\(x+8\\) gives a translation left \\(8\\); \\(\\tfrac12 x\\) gives a horizontal stretch of scale factor \\(2\\). Inside-the-bracket order is innermost first." }, { stepNumber: 3, description: "Relate a root of \\(g\\) to a root of \\(f\\).", workingLatex: "g(x) = 0 \\iff f\\!\\left(\\tfrac12 x + 4\\right) = 0", explanation: "\\(g\\) is zero exactly where its argument equals an \\(x\\)-value at which \\(f\\) is zero. So set the argument equal to the unknown root of \\(f\\)." }, { stepNumber: 4, description: "Substitute the first root \\(x = -2\\).", workingLatex: "\\tfrac12(-2) + 4 = 3", explanation: "The argument evaluates to \\(3\\), so \\(f(3) = 0\\): \\(f\\) has a root at \\(x = 3\\)." }, { stepNumber: 5, description: "Substitute the second root \\(x = 6\\).", workingLatex: "\\tfrac12(6) + 4 = 7", explanation: "The argument evaluates to \\(7\\), so \\(f(7) = 0\\): \\(f\\) has a root at \\(x = 7\\). Note the roots map back, not forward, because we are recovering the original." } ], finalAnswer: "(a) \\(\\tfrac12x+4 = \\tfrac12(x+8)\\); translate left \\(8\\), then horizontal stretch scale factor \\(2\\). (b) \\(f\\) has roots at \\(x = 3\\) and \\(x = 7\\)." } },
  { id: "y2fg6-006", topicRef: "y2fg6", topicTitle: "Combining Transformations 06", difficulty: "Foundation", questionText: "Describe \\(y = f(x) \\to y = -f(x)\\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Negative outside.", workingLatex: "", explanation: "" } ], finalAnswer: "Reflection in the x-axis." } },
  { id: "y2fg6-007", topicRef: "y2fg6", topicTitle: "Combining Transformations 07", difficulty: "Foundation", questionText: "Describe \\(y = f(x) \\to y = f(-x)\\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Negative inside.", workingLatex: "", explanation: "" } ], finalAnswer: "Reflection in the y-axis." } },
  { id: "y2fg6-008", topicRef: "y2fg6", topicTitle: "Combining Transformations 08", difficulty: "Challenge", questionText: "The curve \\( y = f(x) \\) passes through \\((0, 6)\\) and has a minimum at \\((-1, -4)\\). It is transformed to \\( y = -2f(x) + 1 \\). (a) Describe the three transformations in the order they must be applied, and explain why the order of the vertical stretch and the reflection does not affect the result here. (b) Find the image of the minimum point and the image of \\((0, 6)\\), stating the nature of the first image point.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["transformations", "order", "image", "reflection"], workedSolution: { steps: [ { stepNumber: 1, description: "Rewrite to expose the structure.", workingLatex: "y = -2f(x) + 1 = (-1)\\cdot 2 \\cdot f(x) + 1", explanation: "The factor \\(-2\\) is a vertical stretch of scale factor \\(2\\) combined with a reflection in the \\(x\\)-axis; the \\(+1\\) is a translation up \\(1\\)." }, { stepNumber: 2, description: "State the ordered sequence.", workingLatex: "f(x) \\to 2f(x) \\to -2f(x) \\to -2f(x) + 1", explanation: "Vertical stretch scale factor \\(2\\), then reflect in the \\(x\\)-axis, then translate up \\(1\\). The translation must come last: applying \\(+1\\) before the stretch would scale the \\(1\\) as well." }, { stepNumber: 3, description: "Explain the commuting of stretch and reflection.", workingLatex: "(-1)\\cdot(2y) = 2\\cdot(-y)", explanation: "Multiplication is commutative, so reflecting then stretching gives the same \\(y\\)-value as stretching then reflecting. Only the translation is order-sensitive against these two." }, { stepNumber: 4, description: "Image of the minimum \\((-1, -4)\\).", workingLatex: "(-1,\\ -4) \\to (-1,\\ -8) \\to (-1,\\ 8) \\to (-1,\\ 9)", explanation: "Multiply \\(y\\) by \\(2\\): \\(-8\\). Reflect: \\(+8\\). Add \\(1\\): \\(9\\). The \\(x\\)-coordinate never moves. A reflection in the \\(x\\)-axis turns a minimum into a maximum." }, { stepNumber: 5, description: "Image of \\((0, 6)\\).", workingLatex: "(0,\\ 6) \\to (0,\\ 12) \\to (0,\\ -12) \\to (0,\\ -11)", explanation: "Same recipe: \\(\\times 2\\) gives \\(12\\), reflect gives \\(-12\\), add \\(1\\) gives \\(-11\\)." } ], finalAnswer: "(a) Vertical stretch scale factor \\(2\\), reflect in the \\(x\\)-axis, translate up \\(1\\); the stretch and reflection commute because the scalars multiply. (b) Minimum image \\((-1, 9)\\), now a maximum; \\((0,6) \\mapsto (0, -11)\\)." } },
  { id: "y2fg6-009", topicRef: "y2fg6", topicTitle: "Combining Transformations 09", difficulty: "Standard", questionText: "Describe the transformation \\(y = f(x) \\to y = \\tfrac{1}{2}f(x + 3)\\).", marks: 2, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Inside first.", workingLatex: "", explanation: "Translate left 3." }, { stepNumber: 2, description: "Then vertical stretch.", workingLatex: "", explanation: "Factor \\(\\tfrac{1}{2}\\)." } ], finalAnswer: "Left 3, then vertical stretch scale factor \\(\\tfrac{1}{2}\\)." } },
  { id: "y2fg6-010", topicRef: "y2fg6", topicTitle: "Combining Transformations 10", difficulty: "Standard", questionText: "Describe \\(y = f(x) \\to y = -f(x - 2) + 4\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Sequence.", workingLatex: "", explanation: "Right, reflect, up." } ], finalAnswer: "Right 2; reflect in x-axis; up 4." } },
  { id: "y2fg6-011", topicRef: "y2fg6", topicTitle: "Combining Transformations 11", difficulty: "Standard", questionText: "Describe \\(y = f(x) \\to y = f(2x - 4)\\). [Hint: factorise.]", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Factorise.", workingLatex: "f(2(x - 2))", explanation: "" }, { stepNumber: 2, description: "Translate right 2 then horizontal stretch by \\(\\tfrac{1}{2}\\).", workingLatex: "", explanation: "Inner first is key." } ], finalAnswer: "Right 2, then horizontal stretch scale factor \\(\\tfrac{1}{2}\\)." } },
  { id: "y2fg6-012", topicRef: "y2fg6", topicTitle: "Combining Transformations 12", difficulty: "Challenge", questionText: "The curve \\( C \\) has equation \\( y = f(x) \\). After a horizontal stretch and a translation, \\( C \\) maps to the curve with equation \\( y = f(3x + 12) \\). (a) By writing \\( 3x + 12 \\) in the form \\( 3(x + a) \\), give the two transformations in the correct order. (b) A different student instead applies the horizontal stretch (scale factor \\( \\tfrac13 \\)) first and then a translation, and obtains the same curve \\( y = f(3x + 12) \\). State the translation that student must use, and explain why it differs from the answer to part (a).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["transformations", "order", "composite-argument"], workedSolution: { steps: [ { stepNumber: 1, description: "Factorise the argument for the translate-first route.", workingLatex: "3x + 12 = 3(x + 4)", explanation: "Factor out the coefficient \\(3\\): \\(3 \\times 4 = 12\\), so \\(a = 4\\). The bracket form makes the genuine shift visible." }, { stepNumber: 2, description: "Read the ordered pair of transformations for part (a).", workingLatex: "x \\mapsto x + 4 \\ \\text{then} \\ x \\mapsto 3x", explanation: "Innermost first: \\(x+4\\) is a translation left \\(4\\); the outer \\(3x\\) is a horizontal stretch scale factor \\(\\tfrac13\\). This is the translate-then-stretch route." }, { stepNumber: 3, description: "Set up the stretch-first route.", workingLatex: "f(x) \\xrightarrow{\\text{stretch} \\times \\tfrac13} f(3x) \\xrightarrow{\\text{translate}} f(3(x - t))", explanation: "If the stretch is applied first you already have \\(f(3x)\\); a subsequent translation by \\(t\\) replaces \\(x\\) with \\(x - t\\), giving \\(f(3(x-t)) = f(3x - 3t)\\)." }, { stepNumber: 4, description: "Match the two expressions.", workingLatex: "3x - 3t = 3x + 12 \\ \\Rightarrow\\ -3t = 12 \\ \\Rightarrow\\ t = -4", explanation: "Equate arguments. \\(t = -4\\) means a translation left \\(4\\) of the already-stretched curve." }, { stepNumber: 5, description: "Explain the difference.", workingLatex: "\\text{shift } 4 \\ (\\text{before}) \\quad\\text{vs}\\quad \\text{shift } 4 \\ (\\text{after, on a } \\tfrac13\\text{-scaled curve})", explanation: "Both shifts are \\(4\\) to the left in this case, but they act on differently scaled curves: a shift applied before a stretch is itself compressed by the stretch. They coincide numerically only because the shift is measured in the appropriate frame each time — the key point is that order changes the meaning, even when the number looks the same." } ], finalAnswer: "(a) \\(3x+12 = 3(x+4)\\): translate left \\(4\\), then horizontal stretch scale factor \\(\\tfrac13\\). (b) The student must translate left \\(4\\) after the stretch; it acts on the already-compressed curve, so although the number is \\(4\\) it is a translation of a different curve — order determines what the shift acts upon." } },
  { id: "y2fg6-013", topicRef: "y2fg6", topicTitle: "Combining Transformations 13", difficulty: "Standard", questionText: "Describe \\(y = f(\\tfrac{x}{2} - 1)\\) as a sequence from \\(y = f(x)\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Factorise.", workingLatex: "f(\\tfrac{1}{2}(x - 2))", explanation: "" } ], finalAnswer: "Translate right 2, then horizontal stretch scale factor 2." } },
  { id: "y2fg6-014", topicRef: "y2fg6", topicTitle: "Combining Transformations 14", difficulty: "Foundation", questionText: "Describe the transformation \\(y = f(x) \\to y = 3f(x) + 2\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Order.", workingLatex: "", explanation: "" } ], finalAnswer: "Stretch y ×3, then up 2." } },
  { id: "y2fg6-015", topicRef: "y2fg6", topicTitle: "Combining Transformations 15", difficulty: "Challenge", questionText: "The point \\((6, 8)\\) lies on \\( y = f(x) \\). A curve \\( y = g(x) \\) is the image of \\( y = f(x) \\) under, in order, a translation right \\(5\\), a vertical stretch of scale factor \\( \\tfrac14 \\), and a reflection in the \\( x \\)-axis. (a) Write \\( g(x) \\) in terms of \\( f \\). (b) Find the image of \\((6, 8)\\). (c) The curve \\( y = g(x) \\) is now translated up \\(2\\) to give \\( y = h(x) \\). State \\( h(x) \\) in terms of \\( f \\) and find the image of \\((6, 8)\\) on \\( y = h(x) \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["transformations", "order", "image", "find-original"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply the translation right \\(5\\) to the equation.", workingLatex: "y = f(x - 5)", explanation: "A translation right \\(5\\) replaces \\(x\\) with \\(x - 5\\) inside the function. This is the first move, so it sits innermost." }, { stepNumber: 2, description: "Apply the vertical stretch then the reflection.", workingLatex: "y = \\tfrac14 f(x - 5) \\ \\to\\ y = -\\tfrac14 f(x - 5)", explanation: "Stretch scale factor \\(\\tfrac14\\) multiplies the output by \\(\\tfrac14\\); reflecting in the \\(x\\)-axis multiplies by \\(-1\\). So \\(g(x) = -\\tfrac14 f(x-5)\\)." }, { stepNumber: 3, description: "Track \\((6, 8)\\) through the horizontal step.", workingLatex: "(6, 8) \\xrightarrow{\\text{right }5} (11, 8)", explanation: "Translation right \\(5\\) adds \\(5\\) to the \\(x\\)-coordinate; the \\(y\\)-coordinate is unchanged." }, { stepNumber: 4, description: "Track it through the vertical steps.", workingLatex: "(11, 8) \\xrightarrow{\\times \\tfrac14} (11, 2) \\xrightarrow{\\text{reflect}} (11, -2)", explanation: "Multiply \\(y\\) by \\(\\tfrac14\\): \\(8 \\to 2\\). Reflect in the \\(x\\)-axis: \\(2 \\to -2\\). So \\((6,8) \\mapsto (11,-2)\\) on \\(y = g(x)\\)." }, { stepNumber: 5, description: "Translate up \\(2\\) to obtain \\(h\\).", workingLatex: "h(x) = -\\tfrac14 f(x - 5) + 2, \\quad (11, -2) \\xrightarrow{+2} (11, 0)", explanation: "Adding \\(2\\) outside gives \\(h(x) = g(x) + 2\\). The image \\((11,-2)\\) rises by \\(2\\) to \\((11, 0)\\). The translation must be applied last, after the reflection." } ], finalAnswer: "(a) \\(g(x) = -\\tfrac14 f(x - 5)\\). (b) Image is \\((11, -2)\\). (c) \\(h(x) = -\\tfrac14 f(x - 5) + 2\\); image of \\((6,8)\\) is \\((11, 0)\\)." } },
  { id: "y2fg6-016", topicRef: "y2fg6", topicTitle: "Combining Transformations 16", difficulty: "Standard", questionText: "Describe \\(y = 5 - f(x)\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Rewrite.", workingLatex: "-f(x) + 5", explanation: "" } ], finalAnswer: "Reflect in x-axis, then up 5." } },
  { id: "y2fg6-017", topicRef: "y2fg6", topicTitle: "Combining Transformations 17", difficulty: "Challenge", questionText: "Describe the transformation to \\(y = f(1 - x)\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor \\(-1\\).", workingLatex: "f(-(x - 1))", explanation: "" } ], finalAnswer: "Translate right 1, then reflect in y-axis." } },
  { id: "y2fg6-018", topicRef: "y2fg6", topicTitle: "Combining Transformations 18", difficulty: "Challenge", questionText: "Describe \\(y = -2f(-x)\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Combine.", workingLatex: "", explanation: "Two reflections + stretch." } ], finalAnswer: "Reflect in y-axis; reflect in x-axis; vertical stretch ×2." } },
  { id: "y2fg6-019", topicRef: "y2fg6", topicTitle: "Combining Transformations 19", difficulty: "Standard", questionText: "Describe \\(y = f(\\tfrac{1}{3}x) - 2\\).", marks: 2, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "", explanation: "" } ], finalAnswer: "Horizontal stretch factor 3, then down 2." } },
  // ── Image of a point ────
  { id: "y2fg6-020", topicRef: "y2fg6", topicTitle: "Combining Transformations 20", difficulty: "Foundation", questionText: "\\((2, 3)\\) lies on \\(y = f(x)\\). Find its image on \\(y = f(x) + 4\\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Add 4 to y.", workingLatex: "", explanation: "" } ], finalAnswer: "\\((2, 7)\\)." } },
  { id: "y2fg6-021", topicRef: "y2fg6", topicTitle: "Combining Transformations 21", difficulty: "Challenge", questionText: "The points \\((2, 3)\\) and \\((8, 3)\\) both lie on \\( y = f(x) \\) and are the only points of \\( f \\) with \\( y \\)-coordinate \\(3\\). The same two points, in the same order, lie on \\( y = f(ax + b) \\) at \\((1, 3)\\) and \\((4, 3)\\) respectively. (a) Form two equations in \\(a\\) and \\(b\\) and solve them. (b) Hence describe the single sequence of transformations from \\( y = f(x) \\) to \\( y = f(ax + b) \\), with the steps in order.", marks: 7, examStyle: true, yearCreated: 2026, tags: ["transformations", "image", "find-original", "composite-argument"], workedSolution: { steps: [ { stepNumber: 1, description: "Use the fact that the argument must match the original input.", workingLatex: "f(ax + b) = 3 \\iff ax + b \\in \\{2, 8\\}", explanation: "The transformed curve hits \\(y = 3\\) precisely where its argument equals \\(2\\) or \\(8\\), since those are the only inputs giving \\(f = 3\\)." }, { stepNumber: 2, description: "Substitute the image point \\((1, 3)\\), which corresponds to input \\(2\\).", workingLatex: "a(1) + b = 2 \\ \\Rightarrow\\ a + b = 2", explanation: "The point that was at \\(x=2\\) is now at \\(x=1\\), so \\(x=1\\) must produce argument \\(2\\)." }, { stepNumber: 3, description: "Substitute the image point \\((4, 3)\\), which corresponds to input \\(8\\).", workingLatex: "a(4) + b = 8 \\ \\Rightarrow\\ 4a + b = 8", explanation: "The point that was at \\(x=8\\) is now at \\(x=4\\), so \\(x=4\\) must produce argument \\(8\\). Matching points in the stated order avoids a sign error." }, { stepNumber: 4, description: "Solve the simultaneous equations.", workingLatex: "(4a + b) - (a + b) = 8 - 2 \\ \\Rightarrow\\ 3a = 6 \\ \\Rightarrow\\ a = 2, \\ b = 0", explanation: "Subtract the equations to eliminate \\(b\\). Then \\(a = 2\\) and \\(b = 2 - a = 0\\)." }, { stepNumber: 5, description: "Interpret \\(f(2x)\\) as a sequence.", workingLatex: "f(ax + b) = f(2x)", explanation: "With \\(a=2,\\ b=0\\) the map is \\(y = f(2x)\\), a single horizontal stretch of scale factor \\(\\tfrac12\\). There is no translation since \\(b = 0\\); the width \\(8-2=6\\) shrinking to \\(4-1=3\\) confirms the factor \\(\\tfrac12\\)." } ], finalAnswer: "(a) \\(a + b = 2\\) and \\(4a + b = 8\\), giving \\(a = 2,\\ b = 0\\). (b) \\(y = f(2x)\\): a single horizontal stretch of scale factor \\(\\tfrac12\\) (no translation)." } },
  { id: "y2fg6-022", topicRef: "y2fg6", topicTitle: "Combining Transformations 22", difficulty: "Foundation", questionText: "\\((2, 3)\\) lies on \\(y = f(x)\\). Find its image on \\(y = 2f(x)\\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Double y.", workingLatex: "", explanation: "" } ], finalAnswer: "\\((2, 6)\\)." } },
  { id: "y2fg6-023", topicRef: "y2fg6", topicTitle: "Combining Transformations 23", difficulty: "Standard", questionText: "\\((-1, 4)\\) lies on \\(y = f(x)\\). Find its image on \\(y = f(2x)\\).", marks: 2, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Halve x.", workingLatex: "", explanation: "" } ], finalAnswer: "\\((-\\tfrac{1}{2}, 4)\\)." } },
  { id: "y2fg6-024", topicRef: "y2fg6", topicTitle: "Combining Transformations 24", difficulty: "Foundation", questionText: "\\((3, -1)\\) lies on \\(y = f(x)\\). Image on \\(y = -f(x)\\).", marks: 1, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Negate y.", workingLatex: "", explanation: "" } ], finalAnswer: "\\((3, 1)\\)." } },
  { id: "y2fg6-025", topicRef: "y2fg6", topicTitle: "Combining Transformations 25", difficulty: "Challenge", questionText: "The point \\((3, -1)\\) lies on \\( y = f(x) \\). (a) Find the image of \\((3, -1)\\) on \\( y = f(-x) \\), then on \\( y = -f(-x) \\), and finally on \\( y = -f(-x) + 4 \\), showing each stage. (b) The combined transformation \\( y = -f(-x) + 4 \\) can be described as a single rotation followed by a translation. State the rotation (centre and angle) and the translation.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["transformations", "order", "image", "reflection"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply \\(x \\mapsto -x\\) (reflection in the \\(y\\)-axis).", workingLatex: "(3, -1) \\xrightarrow{y = f(-x)} (-3, -1)", explanation: "Replacing \\(x\\) with \\(-x\\) reflects in the \\(y\\)-axis, so the \\(x\\)-coordinate changes sign while \\(y\\) stays fixed." }, { stepNumber: 2, description: "Apply the outer \\(-1\\) (reflection in the \\(x\\)-axis).", workingLatex: "(-3, -1) \\xrightarrow{y = -f(-x)} (-3, 1)", explanation: "Multiplying the whole function by \\(-1\\) reflects in the \\(x\\)-axis, so the \\(y\\)-coordinate changes sign." }, { stepNumber: 3, description: "Apply the \\(+4\\) (translation up \\(4\\)).", workingLatex: "(-3, 1) \\xrightarrow{+4} (-3, 5)", explanation: "Adding \\(4\\) outside the function raises every point by \\(4\\). The translation is applied last." }, { stepNumber: 4, description: "Combine the two reflections.", workingLatex: "(x, y) \\mapsto (-x, -y)", explanation: "Reflecting in the \\(y\\)-axis then the \\(x\\)-axis sends \\((x,y)\\) to \\((-x,-y)\\). That composite is exactly a rotation of \\(180^\\circ\\) about the origin — a key fact: two perpendicular reflections equal a half-turn." }, { stepNumber: 5, description: "State the full description.", workingLatex: "\\text{rotate } 180^\\circ \\text{ about } O, \\ \\text{then translate } \\begin{pmatrix} 0 \\\\ 4 \\end{pmatrix}", explanation: "Check on the point: \\((3,-1)\\) rotated \\(180^\\circ\\) gives \\((-3,1)\\), then up \\(4\\) gives \\((-3,5)\\), matching part (a)." } ], finalAnswer: "(a) \\((3,-1) \\to (-3,-1) \\to (-3,1) \\to (-3,5)\\). (b) Rotation \\(180^\\circ\\) about the origin, then translation \\(4\\) units up." } },
  { id: "y2fg6-026", topicRef: "y2fg6", topicTitle: "Combining Transformations 26", difficulty: "Standard", questionText: "\\((2, 5)\\) lies on \\(y = f(x)\\). Find its image on \\(y = 3f(x - 1) + 2\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Shift right, stretch, shift up.", workingLatex: "(2, 5) \\to (3, 5) \\to (3, 15) \\to (3, 17)", explanation: "" } ], finalAnswer: "\\((3, 17)\\)." } },
  { id: "y2fg6-027", topicRef: "y2fg6", topicTitle: "Combining Transformations 27", difficulty: "Standard", questionText: "\\((-2, 4)\\) lies on \\(y = f(x)\\). Find its image on \\(y = \\tfrac{1}{2}f(x + 3) - 1\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Shift left, halve y, shift down.", workingLatex: "(-2, 4) \\to (-5, 4) \\to (-5, 2) \\to (-5, 1)", explanation: "" } ], finalAnswer: "\\((-5, 1)\\)." } },
  { id: "y2fg6-028", topicRef: "y2fg6", topicTitle: "Combining Transformations 28", difficulty: "Challenge", questionText: "\\((1, 1)\\) lies on \\(y = f(x)\\). Find its image on \\(y = f(2x - 4)\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor inside.", workingLatex: "f(2(x - 2))", explanation: "" }, { stepNumber: 2, description: "Shift right 2 then halve x.", workingLatex: "(1, 1) \\to (3, 1) \\to (\\tfrac{3}{2}, 1)", explanation: "" } ], finalAnswer: "\\((\\tfrac{3}{2}, 1)\\)." } },
  { id: "y2fg6-029", topicRef: "y2fg6", topicTitle: "Combining Transformations 29", difficulty: "Challenge", questionText: "\\((4, -3)\\) lies on \\(y = f(x)\\). Image on \\(y = -f(-x) + 5\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply step by step.", workingLatex: "(4, -3) \\to (-4, -3) \\to (-4, 3) \\to (-4, 8)", explanation: "" } ], finalAnswer: "\\((-4, 8)\\)." } },
  { id: "y2fg6-030", topicRef: "y2fg6", topicTitle: "Combining Transformations 30", difficulty: "Challenge", questionText: "The curve \\( y = f(x) \\) has a maximum at \\((2, 9)\\) and a minimum at \\((6, 1)\\). The curve is transformed to \\( y = 5 - 2f\\!\\left(\\tfrac12 x + 1\\right) \\). (a) Write \\( \\tfrac12 x + 1 \\) as \\( \\tfrac12(x + c) \\) and list every transformation in the order applied. (b) Find the images of both stationary points, stating the nature of each image. (c) State the equation of the line of symmetry between the two image points' \\( y \\)-coordinates is not required — instead, find the vertical distance between the two image points.", marks: 8, examStyle: true, yearCreated: 2026, tags: ["transformations", "order", "composite-argument", "image"], workedSolution: { steps: [ { stepNumber: 1, description: "Factorise the inside argument.", workingLatex: "\\tfrac12 x + 1 = \\tfrac12(x + 2)", explanation: "Take out \\(\\tfrac12\\): since \\(\\tfrac12 \\times 2 = 1\\), we get \\(c = 2\\). The shift is \\(2\\), not \\(1\\)." }, { stepNumber: 2, description: "List inside transformations, innermost first.", workingLatex: "x \\mapsto x + 2 \\ \\text{then} \\ x \\mapsto \\tfrac12 x", explanation: "\\(x+2\\) is a translation left \\(2\\); \\(\\tfrac12 x\\) is a horizontal stretch scale factor \\(2\\)." }, { stepNumber: 3, description: "Rewrite the outside and list those transformations.", workingLatex: "y = 5 - 2f(\\cdots) = -2f(\\cdots) + 5", explanation: "The \\(-2\\) is a vertical stretch scale factor \\(2\\) with a reflection in the \\(x\\)-axis; the \\(+5\\) is a translation up \\(5\\), applied last." }, { stepNumber: 4, description: "Transform the maximum \\((2, 9)\\).", workingLatex: "(2,9) \\xrightarrow{\\text{left }2} (0,9) \\xrightarrow{\\times 2 \\text{ horiz}} (0,9) \\xrightarrow{\\times(-2)} (0,-18) \\xrightarrow{+5} (0,-13)", explanation: "Left \\(2\\): \\(x = 0\\). Horizontal stretch \\(\\times 2\\): \\(x\\) doubles, still \\(0\\). Then \\(y \\times (-2) = -18\\), then \\(+5\\). The reflection turns the maximum into a minimum." }, { stepNumber: 5, description: "Transform the minimum \\((6, 1)\\).", workingLatex: "(6,1) \\xrightarrow{\\text{left }2} (4,1) \\xrightarrow{\\times 2 \\text{ horiz}} (8,1) \\xrightarrow{\\times(-2)} (8,-2) \\xrightarrow{+5} (8,3)", explanation: "Left \\(2\\): \\(x = 4\\). Horizontal stretch \\(\\times 2\\): \\(x = 8\\). Then \\(y \\times (-2) = -2\\), then \\(+5 = 3\\). The reflection turns the minimum into a maximum." }, { stepNumber: 6, description: "Find the vertical distance between the image points.", workingLatex: "|\\,3 - (-13)\\,| = 16", explanation: "The image points are \\((0,-13)\\) and \\((8,3)\\); the vertical gap is the difference of \\(y\\)-coordinates, \\(16\\). The original gap was \\(9 - 1 = 8\\), doubled by the stretch factor \\(2\\), as expected." } ], finalAnswer: "(a) \\(\\tfrac12x+1 = \\tfrac12(x+2)\\); order: translate left \\(2\\), horizontal stretch scale factor \\(2\\), vertical stretch scale factor \\(2\\), reflect in the \\(x\\)-axis, translate up \\(5\\). (b) Maximum \\((2,9) \\mapsto (0,-13)\\), now a minimum; minimum \\((6,1) \\mapsto (8,3)\\), now a maximum. (c) Vertical distance \\(= 16\\)." } },
  // ── Find equation from transformation ────
  { id: "y2fg6-031", topicRef: "y2fg6", topicTitle: "Combining Transformations 31", difficulty: "Foundation", questionText: "Start with \\(y = x^2\\). Stretch vertically ×2 then translate up 1. Write the equation.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply.", workingLatex: "", explanation: "" } ], finalAnswer: "\\(y = 2x^2 + 1\\)." } },
  { id: "y2fg6-032", topicRef: "y2fg6", topicTitle: "Combining Transformations 32", difficulty: "Standard", questionText: "Start with \\(y = \\sin x\\); apply a horizontal stretch scale factor 2. Write the new equation.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "Inside: factor \\(1/2\\).", workingLatex: "", explanation: "" } ], finalAnswer: "\\(y = \\sin(\\tfrac{x}{2})\\)." } },
  { id: "y2fg6-033", topicRef: "y2fg6", topicTitle: "Combining Transformations 33", difficulty: "Standard", questionText: "Start with \\(y = e^x\\); translate right 2, then reflect in the x-axis.", marks: 2, examStyle: true, yearCreated: 2026, tags: ["transformations", "exp"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply.", workingLatex: "", explanation: "" } ], finalAnswer: "\\(y = -e^{x - 2}\\)." } },
  { id: "y2fg6-034", topicRef: "y2fg6", topicTitle: "Combining Transformations 34", difficulty: "Challenge", questionText: "The curve \\( y = \\ln x \\) is transformed, in order, by: a translation right \\(2\\), a vertical stretch of scale factor \\(3\\), and a reflection in the \\( y \\)-axis. (a) Determine the equation of the resulting curve, simplifying the argument of the logarithm. (b) State the equation of the vertical asymptote of the final curve and the exact coordinates of its \\( x \\)-axis intercept.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["transformations", "order", "log", "composite-argument"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply the translation right \\(2\\).", workingLatex: "y = \\ln(x - 2)", explanation: "Translation right \\(2\\) replaces \\(x\\) with \\(x - 2\\) inside the function. This shifts the asymptote from \\(x = 0\\) to \\(x = 2\\)." }, { stepNumber: 2, description: "Apply the vertical stretch of scale factor \\(3\\).", workingLatex: "y = 3\\ln(x - 2)", explanation: "A vertical stretch multiplies the whole output by \\(3\\). The asymptote and intercept positions are unaffected by a vertical stretch." }, { stepNumber: 3, description: "Apply the reflection in the \\(y\\)-axis.", workingLatex: "y = 3\\ln(-x - 2)", explanation: "Reflection in the \\(y\\)-axis replaces \\(x\\) with \\(-x\\) throughout, so \\(x - 2\\) becomes \\(-x - 2\\). A common slip is to change only one occurrence of \\(x\\)." }, { stepNumber: 4, description: "Simplify the argument.", workingLatex: "y = 3\\ln\\big(-(x + 2)\\big)", explanation: "Factor \\(-1\\) from \\(-x-2\\) to write the argument as \\(-(x+2)\\); this form makes the asymptote easy to read." }, { stepNumber: 5, description: "Find the asymptote and intercept.", workingLatex: "-(x+2) = 0 \\Rightarrow x = -2; \\quad 3\\ln(-(x+2)) = 0 \\Rightarrow -(x+2) = 1 \\Rightarrow x = -3", explanation: "The logarithm is undefined when its argument is \\(0\\), giving the asymptote \\(x = -2\\). The curve meets the \\(x\\)-axis when the argument equals \\(1\\) (since \\(\\ln 1 = 0\\)), giving \\(x = -3\\). Check the domain: \\(-(x+2) > 0 \\Rightarrow x < -2\\), and \\(-3 < -2\\), so the intercept is valid." } ], finalAnswer: "(a) \\(y = 3\\ln(-x - 2) = 3\\ln\\big(-(x+2)\\big)\\). (b) Vertical asymptote \\(x = -2\\); \\(x\\)-axis intercept at \\((-3, 0)\\)." } },
  { id: "y2fg6-035", topicRef: "y2fg6", topicTitle: "Combining Transformations 35", difficulty: "Standard", questionText: "Start with \\(y = \\tfrac{1}{x}\\); translate right 2, then up 3.", marks: 2, examStyle: true, yearCreated: 2026, tags: ["transformations", "reciprocal"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply.", workingLatex: "", explanation: "" } ], finalAnswer: "\\(y = \\tfrac{1}{x - 2} + 3\\)." } },
  { id: "y2fg6-036", topicRef: "y2fg6", topicTitle: "Combining Transformations 36", difficulty: "Standard", questionText: "Start with \\(y = x^2\\); apply horizontal stretch scale factor \\(\\tfrac{1}{3}\\), then down 4.", marks: 2, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply.", workingLatex: "", explanation: "" } ], finalAnswer: "\\(y = 9x^2 - 4\\)." } },
  { id: "y2fg6-037", topicRef: "y2fg6", topicTitle: "Combining Transformations 37", difficulty: "Challenge", questionText: "A curve has equation \\( y = a\\cos\\big(b(x - c)\\big) + d \\), where \\(a > 0\\), \\(b > 0\\) and \\(0 \\le c < \\tfrac{\\pi}{2}\\). It is obtained from \\( y = \\cos x \\) and has period \\( \\pi \\), a maximum value of \\(7\\), a minimum value of \\(-1\\), and a maximum point at \\( x = \\tfrac{\\pi}{6} \\). (a) Determine the values of \\(a\\), \\(b\\), \\(c\\) and \\(d\\). (b) Describe, in order, the four transformations that map \\( y = \\cos x \\) onto this curve.", marks: 8, examStyle: true, yearCreated: 2026, tags: ["transformations", "order", "trig", "find-original"], workedSolution: { steps: [ { stepNumber: 1, description: "Use the period to find \\(b\\).", workingLatex: "\\frac{2\\pi}{b} = \\pi \\ \\Rightarrow\\ b = 2", explanation: "The period of \\(\\cos(bx)\\) is \\(\\tfrac{2\\pi}{b}\\). Setting this equal to \\(\\pi\\) gives \\(b = 2\\)." }, { stepNumber: 2, description: "Use the max and min to find \\(a\\) and \\(d\\).", workingLatex: "a + d = 7, \\quad d - a = -1", explanation: "The maximum of \\(a\\cos(\\cdots)+d\\) is \\(a + d\\) and the minimum is \\(d - a\\), since \\(\\cos\\) ranges over \\([-1,1]\\) and \\(a>0\\)." }, { stepNumber: 3, description: "Solve for \\(a\\) and \\(d\\).", workingLatex: "(a+d)+(d-a) = 7 + (-1) \\Rightarrow 2d = 6 \\Rightarrow d = 3, \\ a = 4", explanation: "Add the equations to get \\(d = 3\\); then \\(a = 7 - d = 4\\). So the amplitude is \\(4\\)." }, { stepNumber: 4, description: "Use the maximum location to find \\(c\\).", workingLatex: "\\cos\\big(2(x - c)\\big) = 1 \\text{ at } x = \\tfrac{\\pi}{6} \\Rightarrow 2\\left(\\tfrac{\\pi}{6} - c\\right) = 0", explanation: "A maximum of \\(a\\cos(\\cdots)+d\\) occurs where the cosine equals \\(1\\), i.e. where its argument is \\(0\\). With \\(0 \\le c < \\tfrac{\\pi}{2}\\) we take the argument to be exactly \\(0\\)." }, { stepNumber: 5, description: "Solve for \\(c\\).", workingLatex: "\\tfrac{\\pi}{6} - c = 0 \\ \\Rightarrow\\ c = \\tfrac{\\pi}{6}", explanation: "So \\(c = \\tfrac{\\pi}{6}\\), which lies in the required range. The equation is \\(y = 4\\cos\\big(2(x - \\tfrac{\\pi}{6})\\big) + 3\\)." }, { stepNumber: 6, description: "Describe the ordered transformations.", workingLatex: "\\cos x \\to \\cos(2x) \\to \\cos\\!\\big(2(x-\\tfrac{\\pi}{6})\\big) \\to 4\\cos(\\cdots) \\to 4\\cos(\\cdots)+3", explanation: "Inside the bracket, do the stretch then the shift in the factorised frame: horizontal stretch scale factor \\(\\tfrac12\\) (from \\(b=2\\)), then translation right \\(\\tfrac{\\pi}{6}\\). Outside: vertical stretch scale factor \\(4\\), then translation up \\(3\\). The vertical translation must be last." } ], finalAnswer: "(a) \\(a = 4,\\ b = 2,\\ c = \\tfrac{\\pi}{6},\\ d = 3\\), so \\(y = 4\\cos\\big(2(x - \\tfrac{\\pi}{6})\\big) + 3\\). (b) Horizontal stretch scale factor \\(\\tfrac12\\), translation right \\(\\tfrac{\\pi}{6}\\), vertical stretch scale factor \\(4\\), translation up \\(3\\)." } },
  { id: "y2fg6-038", topicRef: "y2fg6", topicTitle: "Combining Transformations 38", difficulty: "Standard", questionText: "Transform \\(y = x^2\\) so its vertex is at \\((3, -2)\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Complete-square form.", workingLatex: "", explanation: "" } ], finalAnswer: "\\(y = (x - 3)^2 - 2\\)." } },
  { id: "y2fg6-039", topicRef: "y2fg6", topicTitle: "Combining Transformations 39", difficulty: "Standard", questionText: "Transform \\(y = x^3\\) by translating up so it passes through \\((0, 5)\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "\\(y = x^3 + c\\), \\(c = 5\\).", workingLatex: "", explanation: "" } ], finalAnswer: "\\(y = x^3 + 5\\)." } },
  { id: "y2fg6-040", topicRef: "y2fg6", topicTitle: "Combining Transformations 40", difficulty: "Standard", questionText: "Transform \\(y = e^x\\) by horizontal stretch factor \\(\\tfrac{1}{2}\\), then up 1.", marks: 2, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply.", workingLatex: "", explanation: "" } ], finalAnswer: "\\(y = e^{2x} + 1\\)." } },
  // ── Order dependence ────
  { id: "y2fg6-041", topicRef: "y2fg6", topicTitle: "Combining Transformations 41", difficulty: "Challenge", questionText: "The curve \\(y = x^2\\) is transformed by the following chain, in order: a translation by \\(\\begin{pmatrix} -2 \\\\ 0 \\end{pmatrix}\\), then a stretch parallel to the \\(y\\)-axis by scale factor \\(3\\), then a translation by \\(\\begin{pmatrix} 0 \\\\ -5 \\end{pmatrix}\\). (a) Find the equation of the final curve in the form \\(y = a(x + b)^2 + c\\). (b) State the coordinates of the vertex of the final curve. (c) A student performs the same three transformations but applies the \\(y\\)-stretch last instead of in the middle. Show that this changes the equation, and give the new equation.", marks: 7, examStyle: true, yearCreated: 2026, tags: ["transformations", "order", "composite"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply the first translation to \\(y = x^2\\).", workingLatex: "y = (x + 2)^2", explanation: "A translation by \\(\\begin{pmatrix} -2 \\\\ 0 \\end{pmatrix}\\) replaces \\(x\\) with \\(x + 2\\). A common slip is to write \\((x-2)^2\\); a shift left needs \\(+2\\) inside the bracket." }, { stepNumber: 2, description: "Apply the vertical stretch by factor 3.", workingLatex: "y = 3(x + 2)^2", explanation: "A \\(y\\)-stretch of factor 3 multiplies the whole right-hand side by 3, so every \\(y\\)-value is tripled." }, { stepNumber: 3, description: "Apply the final translation down 5.", workingLatex: "y = 3(x + 2)^2 - 5", explanation: "A translation by \\(\\begin{pmatrix} 0 \\\\ -5 \\end{pmatrix}\\) subtracts 5 from the whole expression, after the stretch has acted." }, { stepNumber: 4, description: "Read off the vertex of the completed-square form.", workingLatex: "y = 3(x + 2)^2 - 5 \\Rightarrow \\text{vertex } (-2,\\ -5)", explanation: "In the form \\(a(x+b)^2 + c\\) the vertex is \\((-b, c)\\). The bracket is least (zero) when \\(x = -2\\), giving \\(y = -5\\)." }, { stepNumber: 5, description: "Perform the alternative order: translate left, translate down, then stretch.", workingLatex: "y = (x+2)^2 \\;\\to\\; y = (x+2)^2 - 5 \\;\\to\\; y = 3\\big[(x+2)^2 - 5\\big]", explanation: "With the stretch last, the down-5 translation happens before the stretch, so the \\(-5\\) is also multiplied by 3." }, { stepNumber: 6, description: "Expand and compare with part (a).", workingLatex: "y = 3(x+2)^2 - 15 \\neq 3(x+2)^2 - 5", explanation: "The constant is \\(-15\\) not \\(-5\\): a vertical stretch and a vertical translation do not commute, because the stretch scales any translation applied before it." } ], finalAnswer: "(a) \\(y = 3(x + 2)^2 - 5\\). (b) Vertex \\((-2,\\ -5)\\). (c) Stretching last gives \\(y = 3(x+2)^2 - 15\\), which differs from (a), so the order matters." } },
  { id: "y2fg6-042", topicRef: "y2fg6", topicTitle: "Combining Transformations 42", difficulty: "Challenge", questionText: "(a) Start with \\(y = f(x)\\); stretch horizontally ×\\(\\tfrac{1}{2}\\) then translate right 4. (b) Reverse order. Compare.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "(a).", workingLatex: "y = f(2(x - 4)) = f(2x - 8)", explanation: "" }, { stepNumber: 2, description: "(b) Translate then stretch.", workingLatex: "y = f(2x - 4)", explanation: "" } ], finalAnswer: "Different: \\(f(2x - 8)\\) vs \\(f(2x - 4)\\)." } },
  { id: "y2fg6-043", topicRef: "y2fg6", topicTitle: "Combining Transformations 43", difficulty: "Standard", questionText: "Apply to \\(y = x^2\\): (a) reflect in x-axis then up 4, (b) up 4 then reflect. Compare.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "(a)", workingLatex: "y = -x^2 + 4", explanation: "" }, { stepNumber: 2, description: "(b)", workingLatex: "y = -(x^2 + 4) = -x^2 - 4", explanation: "" } ], finalAnswer: "Different: \\(-x^2 + 4\\) vs \\(-x^2 - 4\\)." } },
  // ── Identify transformation from equation ────
  { id: "y2fg6-044", topicRef: "y2fg6", topicTitle: "Combining Transformations 44", difficulty: "Foundation", questionText: "Describe the transformations from \\(y = x^2\\) to \\(y = (x + 3)^2 - 5\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Inside: left 3. Outside: down 5.", workingLatex: "", explanation: "" } ], finalAnswer: "Left 3, then down 5." } },
  { id: "y2fg6-045", topicRef: "y2fg6", topicTitle: "Combining Transformations 45", difficulty: "Standard", questionText: "Describe the transformations from \\(y = \\sin x\\) to \\(y = 2\\sin(3x)\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "", explanation: "" } ], finalAnswer: "Horizontal stretch factor \\(\\tfrac{1}{3}\\); vertical stretch factor 2." } },
  { id: "y2fg6-046", topicRef: "y2fg6", topicTitle: "Combining Transformations 46", difficulty: "Challenge", questionText: "The curve \\(C\\) has equation \\(y = 2e^{3x - 6} - 1\\). (a) By writing \\(3x - 6 = 3(x - 2)\\), describe fully the sequence of three single transformations that maps \\(y = e^x\\) onto \\(C\\), giving them in a valid order. (b) Hence find the exact coordinates of the point where \\(C\\) crosses the \\(x\\)-axis. (c) State the equation of the horizontal asymptote of \\(C\\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["transformations", "exp", "composite-argument", "order"], workedSolution: { steps: [ { stepNumber: 1, description: "Factorise the argument of the exponential.", workingLatex: "y = 2e^{3(x - 2)} - 1", explanation: "Inside the function you must factorise the coefficient of \\(x\\) out before reading a translation. The factor 3 signals a horizontal stretch; the \\(-2\\) inside the bracket signals a horizontal translation." }, { stepNumber: 2, description: "Identify the horizontal stretch.", workingLatex: "e^x \\to e^{3x}: \\text{ stretch in } x \\text{ by factor } \\tfrac{1}{3}", explanation: "Replacing \\(x\\) with \\(3x\\) compresses horizontally: scale factor \\(\\tfrac{1}{3}\\). A common slip is to call this factor 3." }, { stepNumber: 3, description: "Identify the horizontal translation.", workingLatex: "e^{3x} \\to e^{3(x-2)}: \\text{ translation } \\begin{pmatrix} 2 \\\\ 0 \\end{pmatrix}", explanation: "The bracket \\((x - 2)\\) shifts the curve right by 2. Because we factorised first, the shift is genuinely 2, not 6." }, { stepNumber: 4, description: "Identify the vertical stretch and vertical translation.", workingLatex: "e^{3(x-2)} \\to 2e^{3(x-2)} \\to 2e^{3(x-2)} - 1", explanation: "Multiplying by 2 is a \\(y\\)-stretch of factor 2; subtracting 1 is a translation by \\(\\begin{pmatrix} 0 \\\\ -1 \\end{pmatrix}\\). The \\(y\\)-stretch must precede the \\(y\\)-shift for this equation to result." }, { stepNumber: 5, description: "Find the x-intercept by setting y = 0.", workingLatex: "2e^{3x-6} - 1 = 0 \\Rightarrow e^{3x-6} = \\tfrac{1}{2}", explanation: "The curve crosses the \\(x\\)-axis where \\(y = 0\\). Isolate the exponential before taking logs." }, { stepNumber: 6, description: "Solve for x using natural logarithms.", workingLatex: "3x - 6 = \\ln\\tfrac{1}{2} = -\\ln 2 \\Rightarrow x = 2 - \\tfrac{\\ln 2}{3}", explanation: "Take \\(\\ln\\) of both sides and rearrange. Keep the answer exact; \\(\\ln\\tfrac12 = -\\ln 2\\) tidies the form." }, { stepNumber: 7, description: "State the asymptote.", workingLatex: "y = -1", explanation: "As \\(x \\to -\\infty\\), \\(e^{3x-6} \\to 0\\), so \\(y \\to 2(0) - 1 = -1\\). The vertical translation moves the asymptote from \\(y = 0\\) to \\(y = -1\\)." } ], finalAnswer: "(a) Horizontal stretch factor \\(\\tfrac{1}{3}\\), then translation \\(\\begin{pmatrix} 2 \\\\ 0 \\end{pmatrix}\\), then \\(y\\)-stretch factor 2, then translation \\(\\begin{pmatrix} 0 \\\\ -1 \\end{pmatrix}\\). (b) \\(\\left(2 - \\tfrac{\\ln 2}{3},\\ 0\\right)\\). (c) \\(y = -1\\)." } },
  { id: "y2fg6-047", topicRef: "y2fg6", topicTitle: "Combining Transformations 47", difficulty: "Standard", questionText: "Describe \\(y = \\tfrac{1}{x} \\to y = \\tfrac{2}{x} + 1\\).", marks: 2, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "", explanation: "" } ], finalAnswer: "Vertical stretch ×2, then up 1." } },
  { id: "y2fg6-048", topicRef: "y2fg6", topicTitle: "Combining Transformations 48", difficulty: "Standard", questionText: "Describe \\(y = x^2 \\to y = 4 - (x - 1)^2\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Right, reflect, up.", workingLatex: "", explanation: "" } ], finalAnswer: "Right 1, reflect in x-axis, up 4." } },
  { id: "y2fg6-049", topicRef: "y2fg6", topicTitle: "Combining Transformations 49", difficulty: "Challenge", questionText: "The curve \\(y = \\cos x\\) is mapped onto the curve \\(y = g(x)\\) by, in order: a stretch parallel to the \\(x\\)-axis by scale factor \\(\\tfrac{1}{2}\\), then a reflection in the \\(x\\)-axis, then a translation by \\(\\begin{pmatrix} \\frac{\\pi}{4} \\\\ 0 \\end{pmatrix}\\). (a) Find \\(g(x)\\) in the form \\(-\\cos(a x + b)\\), stating \\(a\\) and \\(b\\). (b) Show that \\(g(x)\\) can also be written as \\(\\cos(2x - \\tfrac{\\pi}{4})\\), and explain which trig identity makes the reflection 'disappear'. (c) State the smallest positive value of \\(x\\) at which \\(g(x)\\) attains its maximum value.", marks: 7, examStyle: true, yearCreated: 2026, tags: ["transformations", "trig", "order", "composite-argument"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply the horizontal stretch by factor 1/2.", workingLatex: "y = \\cos x \\to y = \\cos(2x)", explanation: "A horizontal stretch of factor \\(\\tfrac{1}{2}\\) replaces \\(x\\) with \\(2x\\). The reciprocal relationship is the usual trap: factor \\(\\tfrac12\\) means multiply \\(x\\) by 2." }, { stepNumber: 2, description: "Apply the reflection in the x-axis.", workingLatex: "y = \\cos(2x) \\to y = -\\cos(2x)", explanation: "Reflection in the \\(x\\)-axis negates the whole output: \\(y \\to -y\\)." }, { stepNumber: 3, description: "Apply the translation right by pi/4.", workingLatex: "y = -\\cos\\big(2(x - \\tfrac{\\pi}{4})\\big) = -\\cos(2x - \\tfrac{\\pi}{2})", explanation: "Translating right by \\(\\tfrac{\\pi}{4}\\) replaces \\(x\\) with \\(x - \\tfrac{\\pi}{4}\\); distributing the 2 gives the argument \\(2x - \\tfrac{\\pi}{2}\\). So \\(a = 2,\\ b = -\\tfrac{\\pi}{2}\\)." }, { stepNumber: 4, description: "Rewrite using a cosine shift identity.", workingLatex: "-\\cos\\theta = \\cos(\\theta - \\pi) \\ \\text{or}\\ \\cos(\\theta + \\pi)", explanation: "Since \\(\\cos\\) has period \\(2\\pi\\) and \\(\\cos(\\theta - \\pi) = -\\cos\\theta\\), a half-period shift absorbs the minus sign." }, { stepNumber: 5, description: "Apply that identity to g(x).", workingLatex: "g(x) = -\\cos(2x - \\tfrac{\\pi}{2}) = \\cos(2x - \\tfrac{\\pi}{2} - \\pi) = \\cos(2x - \\tfrac{3\\pi}{2})", explanation: "And \\(\\cos\\) is \\(2\\pi\\)-periodic, so \\(\\cos(2x - \\tfrac{3\\pi}{2}) = \\cos(2x - \\tfrac{3\\pi}{2} + 2\\pi) = \\cos(2x + \\tfrac{\\pi}{2})\\). Care: that is not \\(\\cos(2x - \\tfrac{\\pi}{4})\\)." }, { stepNumber: 6, description: "Verify the claimed form directly.", workingLatex: "\\cos(2x - \\tfrac{\\pi}{4}) \\ \\text{vs}\\ -\\cos(2x - \\tfrac{\\pi}{2}) = \\cos(2x + \\tfrac{\\pi}{2})", explanation: "At \\(x = 0\\): \\(\\cos(-\\tfrac{\\pi}{4}) = \\tfrac{\\sqrt2}{2}\\) but \\(\\cos(\\tfrac{\\pi}{2}) = 0\\). The two are not equal, so the claim in (b) is false; the correct simplified form is \\(g(x) = \\cos(2x + \\tfrac{\\pi}{2})\\)." }, { stepNumber: 7, description: "Find the first maximum of g(x).", workingLatex: "g(x) = \\cos(2x + \\tfrac{\\pi}{2}) = 1 \\Rightarrow 2x + \\tfrac{\\pi}{2} = 2\\pi \\Rightarrow x = \\tfrac{3\\pi}{4}", explanation: "Maximum of cosine is 1, reached when the argument is a multiple of \\(2\\pi\\). The smallest positive \\(x\\) comes from the argument \\(2\\pi\\) (the argument \\(0\\) gives \\(x = -\\tfrac{\\pi}{4} < 0\\))." } ], finalAnswer: "(a) \\(g(x) = -\\cos(2x - \\tfrac{\\pi}{2})\\), so \\(a = 2,\\ b = -\\tfrac{\\pi}{2}\\). (b) The claim is incorrect: using \\(-\\cos\\theta = \\cos(\\theta+\\pi)\\) and \\(2\\pi\\)-periodicity gives \\(g(x) = \\cos(2x + \\tfrac{\\pi}{2})\\), not \\(\\cos(2x - \\tfrac{\\pi}{4})\\). (c) \\(x = \\tfrac{3\\pi}{4}\\)." } },
  { id: "y2fg6-050", topicRef: "y2fg6", topicTitle: "Combining Transformations 50", difficulty: "Standard", questionText: "Describe \\(y = \\sqrt x \\to y = \\sqrt{2x} + 1\\).", marks: 2, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Horizontal shrink then up.", workingLatex: "", explanation: "" } ], finalAnswer: "Horizontal stretch factor \\(\\tfrac{1}{2}\\), then up 1." } },
  // ── Finding the original ────
  { id: "y2fg6-051", topicRef: "y2fg6", topicTitle: "Combining Transformations 51", difficulty: "Challenge", questionText: "\\(y = 2f(x + 3) - 1\\) passes through \\((0, 5)\\). Find \\(f(3)\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute.", workingLatex: "2f(3) - 1 = 5 \\Rightarrow f(3) = 3", explanation: "" } ], finalAnswer: "\\( f(3) = 3 \\)." } },
  { id: "y2fg6-052", topicRef: "y2fg6", topicTitle: "Combining Transformations 52", difficulty: "Challenge", questionText: "\\(y = f(2x - 4)\\) passes through \\((3, 7)\\). What point does \\(y = f(x)\\) pass through?", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Plug in.", workingLatex: "f(2 \\cdot 3 - 4) = f(2) = 7", explanation: "" } ], finalAnswer: "\\((2, 7)\\)." } },
  { id: "y2fg6-053", topicRef: "y2fg6", topicTitle: "Combining Transformations 53", difficulty: "Standard", questionText: "\\(f(4) = 10\\). Find the value of \\(3f(x - 1) + 2\\) at \\(x = 5\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Substitute.", workingLatex: "3f(4) + 2 = 32", explanation: "" } ], finalAnswer: "\\(32\\)." } },
  { id: "y2fg6-054", topicRef: "y2fg6", topicTitle: "Combining Transformations 54", difficulty: "Challenge", questionText: "The graph \\(y = f(x)\\) has a max at \\((5, 8)\\). The graph \\(y = af(x - 2) - 3\\) has max at \\((7, 9)\\). Find \\(a\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Height after stretch and shift.", workingLatex: "8a - 3 = 9 \\Rightarrow a = \\tfrac{3}{2}", explanation: "" } ], finalAnswer: "\\( a = \\tfrac{3}{2} \\)." } },
  // ── Specific common transformations ────
  { id: "y2fg6-055", topicRef: "y2fg6", topicTitle: "Combining Transformations 55", difficulty: "Foundation", questionText: "Describe \\(y = x^2 \\to y = (x - 2)^2 + 3\\) and state the vertex.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Right 2, up 3.", workingLatex: "", explanation: "" } ], finalAnswer: "Vertex \\((2, 3)\\)." } },
  { id: "y2fg6-056", topicRef: "y2fg6", topicTitle: "Combining Transformations 56", difficulty: "Challenge", questionText: "Describe \\(y = x^2 \\to y = -\\tfrac{1}{2}(x + 1)^2 + 4\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Inside left, reflect, stretch \\(\\tfrac{1}{2}\\), up 4.", workingLatex: "", explanation: "" } ], finalAnswer: "Left 1; reflect in x-axis; vertical stretch ×\\(\\tfrac{1}{2}\\); up 4. Vertex \\((-1, 4)\\)." } },
  { id: "y2fg6-057", topicRef: "y2fg6", topicTitle: "Combining Transformations 57", difficulty: "Challenge", questionText: "The function \\(y = f(x)\\) has a single maximum point at \\((-4, 6)\\) and a single minimum point at \\((2, -3)\\). The curve \\(y = h(x)\\) is obtained from \\(y = f(x)\\) by the transformation \\(h(x) = 2 - 3f\\!\\left(\\tfrac{1}{2}x + 1\\right)\\). (a) By writing \\(\\tfrac{1}{2}x + 1 = \\tfrac{1}{2}(x + 2)\\), describe the full sequence of transformations mapping \\(f\\) to \\(h\\). (b) Find the coordinates of the image of the point \\((-4, 6)\\) on \\(y = h(x)\\), stating whether it is a maximum or minimum of \\(h\\). (c) Find the coordinates of the image of \\((2, -3)\\) on \\(y = h(x)\\).", marks: 7, examStyle: true, yearCreated: 2026, tags: ["transformations", "image", "composite-argument", "order"], workedSolution: { steps: [ { stepNumber: 1, description: "Factorise the argument inside f.", workingLatex: "h(x) = 2 - 3f\\big(\\tfrac{1}{2}(x + 2)\\big)", explanation: "Factor the \\(\\tfrac12\\) out of \\(\\tfrac12 x + 1\\). The factor \\(\\tfrac12\\) gives a horizontal stretch; the \\((x+2)\\) gives a horizontal translation. Reading them off before factorising is the classic error." }, { stepNumber: 2, description: "Describe the horizontal transformations.", workingLatex: "f(x) \\to f(\\tfrac12 x): \\text{ stretch in } x \\text{ factor } 2; \\quad \\to f(\\tfrac12(x+2)): \\text{ translate } \\begin{pmatrix} -2 \\\\ 0 \\end{pmatrix}", explanation: "Replacing \\(x\\) by \\(\\tfrac12 x\\) is a horizontal stretch of factor 2 (reciprocal of \\(\\tfrac12\\)); then \\((x+2)\\) shifts left by 2." }, { stepNumber: 3, description: "Describe the vertical transformations.", workingLatex: "f \\to -3f: \\text{ } y\\text{-stretch factor } 3 \\text{ and reflect in } x\\text{-axis}; \\quad \\to 2 - 3f: \\text{ translate } \\begin{pmatrix} 0 \\\\ 2 \\end{pmatrix}", explanation: "Multiplying by \\(-3\\) reflects in the \\(x\\)-axis and stretches vertically by 3; adding 2 then translates up 2. The \\(y\\)-stretch/reflection must come before the \\(+2\\)." }, { stepNumber: 4, description: "Transform the x-coordinate of (-4, 6).", workingLatex: "x' = 2(-4) - 2 = -10", explanation: "Horizontal stretch factor 2 doubles the \\(x\\)-coordinate; the translation then subtracts 2. Equivalently solve \\(\\tfrac12 x' + 1 = -4\\)." }, { stepNumber: 5, description: "Transform the y-coordinate of (-4, 6).", workingLatex: "y' = 2 - 3(6) = -16", explanation: "Apply \\(y \\mapsto 2 - 3y\\) to the output. Because of the reflection (negative factor), a maximum of \\(f\\) becomes a minimum of \\(h\\)." }, { stepNumber: 6, description: "Transform the x-coordinate of (2, -3).", workingLatex: "x' = 2(2) - 2 = 2", explanation: "Same horizontal rule: double then subtract 2. Here it happens to map back to \\(x = 2\\)." }, { stepNumber: 7, description: "Transform the y-coordinate of (2, -3).", workingLatex: "y' = 2 - 3(-3) = 11", explanation: "Apply \\(y \\mapsto 2 - 3y\\). The reflection turns the minimum of \\(f\\) into a maximum of \\(h\\)." } ], finalAnswer: "(a) Horizontal stretch factor 2, then translation \\(\\begin{pmatrix} -2 \\\\ 0 \\end{pmatrix}\\), then a reflection in the \\(x\\)-axis combined with a vertical stretch factor 3, then translation \\(\\begin{pmatrix} 0 \\\\ 2 \\end{pmatrix}\\). (b) \\((-10,\\ -16)\\), a minimum of \\(h\\). (c) \\((2,\\ 11)\\), a maximum of \\(h\\)." } },
  { id: "y2fg6-058", topicRef: "y2fg6", topicTitle: "Combining Transformations 58", difficulty: "Standard", questionText: "\\(y = f(x)\\) has roots at \\(x = -1, 2, 4\\). Roots of \\(y = f(x - 3)\\)?", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Shift right by 3.", workingLatex: "", explanation: "" } ], finalAnswer: "\\(x = 2, 5, 7\\)." } },
  { id: "y2fg6-059", topicRef: "y2fg6", topicTitle: "Combining Transformations 59", difficulty: "Standard", questionText: "\\(y = f(x)\\) has roots at \\(-2, 4\\). Roots of \\(y = f(2x)\\)?", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Halve.", workingLatex: "", explanation: "" } ], finalAnswer: "\\(x = -1, 2\\)." } },
  { id: "y2fg6-060", topicRef: "y2fg6", topicTitle: "Combining Transformations 60", difficulty: "Challenge", questionText: "A curve \\(C\\) is obtained from \\(y = \\tfrac{1}{x}\\) by applying, in order: a stretch parallel to the \\(x\\)-axis by scale factor \\(\\tfrac{1}{2}\\), then a translation by \\(\\begin{pmatrix} 3 \\\\ 0 \\end{pmatrix}\\), then a translation by \\(\\begin{pmatrix} 0 \\\\ -4 \\end{pmatrix}\\). (a) Show that \\(C\\) has equation \\(y = \\dfrac{1}{2x - 6} - 4\\). (b) State the equations of the two asymptotes of \\(C\\). (c) Find the exact coordinates of both intercepts of \\(C\\) with the coordinate axes.", marks: 7, examStyle: true, yearCreated: 2026, tags: ["transformations", "order", "asymptote", "composite-argument"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply the horizontal stretch by factor 1/2.", workingLatex: "y = \\tfrac{1}{x} \\to y = \\tfrac{1}{2x}", explanation: "A horizontal stretch of factor \\(\\tfrac12\\) replaces \\(x\\) with \\(2x\\). The reciprocal of the scale factor goes inside the function." }, { stepNumber: 2, description: "Apply the translation right by 3.", workingLatex: "y = \\tfrac{1}{2x} \\to y = \\tfrac{1}{2(x - 3)} = \\tfrac{1}{2x - 6}", explanation: "Translating right by 3 replaces \\(x\\) with \\(x - 3\\) everywhere it appears, including inside the \\(2x\\) term. Distribute carefully: \\(2(x-3) = 2x - 6\\)." }, { stepNumber: 3, description: "Apply the translation down by 4.", workingLatex: "y = \\tfrac{1}{2x - 6} - 4", explanation: "A translation by \\(\\begin{pmatrix} 0 \\\\ -4 \\end{pmatrix}\\) subtracts 4 from the whole expression, confirming the required equation." }, { stepNumber: 4, description: "Find the vertical asymptote.", workingLatex: "2x - 6 = 0 \\Rightarrow x = 3", explanation: "The vertical asymptote occurs where the denominator is zero. The original \\(x = 0\\) maps under the stretch and shift to \\(x = 3\\)." }, { stepNumber: 5, description: "Find the horizontal asymptote.", workingLatex: "x \\to \\pm\\infty \\Rightarrow \\tfrac{1}{2x-6} \\to 0 \\Rightarrow y \\to -4", explanation: "As \\(x\\) grows the fraction vanishes, leaving \\(y = -4\\). The down-4 translation moves the asymptote from \\(y = 0\\) to \\(y = -4\\)." }, { stepNumber: 6, description: "Find the y-intercept (set x = 0).", workingLatex: "y = \\tfrac{1}{-6} - 4 = -\\tfrac{1}{6} - 4 = -\\tfrac{25}{6}", explanation: "Substitute \\(x = 0\\). Combine over a common denominator: \\(-\\tfrac16 - \\tfrac{24}{6} = -\\tfrac{25}{6}\\)." }, { stepNumber: 7, description: "Find the x-intercept (set y = 0).", workingLatex: "\\tfrac{1}{2x-6} = 4 \\Rightarrow 2x - 6 = \\tfrac{1}{4} \\Rightarrow x = \\tfrac{25}{8}", explanation: "Set \\(y = 0\\), isolate the fraction, then invert. Solve \\(2x = 6 + \\tfrac14 = \\tfrac{25}{4}\\), so \\(x = \\tfrac{25}{8}\\)." } ], finalAnswer: "(a) Shown: \\(y = \\dfrac{1}{2x - 6} - 4\\). (b) Asymptotes \\(x = 3\\) and \\(y = -4\\). (c) \\(y\\)-intercept \\(\\left(0,\\ -\\tfrac{25}{6}\\right)\\); \\(x\\)-intercept \\(\\left(\\tfrac{25}{8},\\ 0\\right)\\)." } },
  { id: "y2fg6-061", topicRef: "y2fg6", topicTitle: "Combining Transformations 61", difficulty: "Standard", questionText: "Asymptote of \\(y = e^{x - 1} - 4\\)?", marks: 2, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Horizontal asymptote shifts by translation.", workingLatex: "", explanation: "" } ], finalAnswer: "\\(y = -4\\)." } },
  // ── Practical / algebraic ────
  { id: "y2fg6-062", topicRef: "y2fg6", topicTitle: "Combining Transformations 62", difficulty: "Challenge", questionText: "\\(y = f(x)\\) passes through \\((0, 0)\\). Find two transformations so the new graph passes through \\((1, 2)\\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Many possible answers.", workingLatex: "", explanation: "" } ], finalAnswer: "One valid answer: right 1 then up 2 (giving \\(y = f(x - 1) + 2\\))." } },
  { id: "y2fg6-063", topicRef: "y2fg6", topicTitle: "Combining Transformations 63", difficulty: "Standard", questionText: "Find \\(a, b, c\\) so that \\(y = a(x - b)^2 + c\\) has vertex at \\((3, -4)\\) and passes through \\((5, 0)\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "\\(b = 3, c = -4\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Substitute \\((5, 0)\\).", workingLatex: "0 = 4a - 4 \\Rightarrow a = 1", explanation: "" } ], finalAnswer: "\\(a = 1, b = 3, c = -4\\)." } },
  { id: "y2fg6-064", topicRef: "y2fg6", topicTitle: "Combining Transformations 64", difficulty: "Standard", questionText: "Apply (i) horizontal stretch factor 3 then (ii) up 4 to \\((1, 2)\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply.", workingLatex: "(1, 2) \\to (3, 2) \\to (3, 6)", explanation: "" } ], finalAnswer: "\\((3, 6)\\)." } },
  { id: "y2fg6-065", topicRef: "y2fg6", topicTitle: "Combining Transformations 65", difficulty: "Challenge", questionText: "Apply to \\((-2, 5)\\): reflect in y-axis, vertical stretch ×\\(\\tfrac{1}{2}\\), then left 3.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply.", workingLatex: "(-2, 5) \\to (2, 5) \\to (2, 2.5) \\to (-1, 2.5)", explanation: "" } ], finalAnswer: "\\((-1, 2.5)\\)." } },
  { id: "y2fg6-066", topicRef: "y2fg6", topicTitle: "Combining Transformations 66", difficulty: "Challenge", questionText: "Find \\(k\\) so that \\(y = f(x - k)\\) passes through the origin, given \\(f(5) = 0\\).", marks: 2, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "At origin, \\(f(-k) = 0\\).", workingLatex: "-k = 5 \\Rightarrow k = -5", explanation: "" } ], finalAnswer: "\\(k = -5\\)." } },
  { id: "y2fg6-067", topicRef: "y2fg6", topicTitle: "Combining Transformations 67", difficulty: "Challenge", questionText: "The curve \\(y = \\tan x\\) is transformed to the curve \\(y = g(x)\\) where \\(g(x) = \\tan\\!\\left(2x + \\tfrac{\\pi}{3}\\right) - 1\\). (a) By writing the argument in the form \\(2\\left(x + \\tfrac{\\pi}{6}\\right)\\), describe fully the sequence of three transformations mapping \\(y = \\tan x\\) onto \\(y = g(x)\\). (b) State the period of \\(y = g(x)\\). (c) The vertical asymptote of \\(y = \\tan x\\) nearest to \\(x = 0\\) on the positive side is \\(x = \\tfrac{\\pi}{2}\\). Find the image of this asymptote on \\(y = g(x)\\), and hence write down the smallest positive \\(x\\)-coordinate of an asymptote of \\(g\\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["transformations", "trig", "composite-argument", "asymptote"], workedSolution: { steps: [ { stepNumber: 1, description: "Factorise the argument of the tangent.", workingLatex: "g(x) = \\tan\\big(2(x + \\tfrac{\\pi}{6})\\big) - 1", explanation: "Factor the coefficient 2 out of \\(2x + \\tfrac{\\pi}{3}\\). The 2 gives a horizontal stretch; the \\((x + \\tfrac{\\pi}{6})\\) gives a horizontal translation." }, { stepNumber: 2, description: "Identify the horizontal stretch.", workingLatex: "\\tan x \\to \\tan(2x): \\text{ stretch in } x \\text{ factor } \\tfrac{1}{2}", explanation: "Replacing \\(x\\) by \\(2x\\) compresses horizontally with scale factor \\(\\tfrac12\\). Halving the input scale halves the period too." }, { stepNumber: 3, description: "Identify the horizontal translation.", workingLatex: "\\tan(2x) \\to \\tan(2(x + \\tfrac{\\pi}{6})): \\text{ translation } \\begin{pmatrix} -\\tfrac{\\pi}{6} \\\\ 0 \\end{pmatrix}", explanation: "The bracket \\((x + \\tfrac{\\pi}{6})\\) shifts left by \\(\\tfrac{\\pi}{6}\\). Because we factorised first, the shift is \\(\\tfrac{\\pi}{6}\\), not \\(\\tfrac{\\pi}{3}\\)." }, { stepNumber: 4, description: "Identify the vertical translation.", workingLatex: "\\tan(2(x + \\tfrac{\\pi}{6})) \\to \\tan(2(x + \\tfrac{\\pi}{6})) - 1: \\text{ translation } \\begin{pmatrix} 0 \\\\ -1 \\end{pmatrix}", explanation: "Subtracting 1 from the whole expression shifts the curve down by 1." }, { stepNumber: 5, description: "State the period of g.", workingLatex: "\\text{period of } \\tan x = \\pi \\Rightarrow \\text{period of } g = \\tfrac{\\pi}{2}", explanation: "The horizontal stretch factor \\(\\tfrac12\\) divides the period by 2; vertical transformations do not change the period." }, { stepNumber: 6, description: "Transform the asymptote x = pi/2.", workingLatex: "2x + \\tfrac{\\pi}{3} = \\tfrac{\\pi}{2} \\Rightarrow 2x = \\tfrac{\\pi}{6} \\Rightarrow x = \\tfrac{\\pi}{12}", explanation: "An asymptote of \\(\\tan\\) occurs where its argument equals \\(\\tfrac{\\pi}{2}\\). Set the new argument equal to \\(\\tfrac{\\pi}{2}\\) and solve. Equivalently, stretch \\(\\tfrac{\\pi}{2}\\) by \\(\\tfrac12\\) to get \\(\\tfrac{\\pi}{4}\\), then shift left \\(\\tfrac{\\pi}{6}\\): \\(\\tfrac{\\pi}{4} - \\tfrac{\\pi}{6} = \\tfrac{\\pi}{12}\\)." }, { stepNumber: 7, description: "Identify the smallest positive asymptote.", workingLatex: "x = \\tfrac{\\pi}{12} + k\\cdot\\tfrac{\\pi}{2}; \\quad \\text{smallest positive} = \\tfrac{\\pi}{12}", explanation: "Asymptotes repeat every period \\(\\tfrac{\\pi}{2}\\). The image \\(x = \\tfrac{\\pi}{12}\\) is already positive and is the smallest such value." } ], finalAnswer: "(a) Horizontal stretch factor \\(\\tfrac{1}{2}\\), then translation \\(\\begin{pmatrix} -\\tfrac{\\pi}{6} \\\\ 0 \\end{pmatrix}\\), then translation \\(\\begin{pmatrix} 0 \\\\ -1 \\end{pmatrix}\\). (b) Period \\(\\tfrac{\\pi}{2}\\). (c) The asymptote \\(x = \\tfrac{\\pi}{2}\\) maps to \\(x = \\tfrac{\\pi}{12}\\), which is the smallest positive asymptote of \\(g\\)." } },
  { id: "y2fg6-068", topicRef: "y2fg6", topicTitle: "Combining Transformations 68", difficulty: "Challenge", questionText: "Start with \\(y = \\ln x\\); apply horizontal stretch factor 2, then reflect in x-axis, then up 1. Write the equation.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply in order.", workingLatex: "y = -\\ln(\\tfrac{x}{2}) + 1", explanation: "" } ], finalAnswer: "\\(y = 1 - \\ln(\\tfrac{x}{2})\\)." } },
  { id: "y2fg6-069", topicRef: "y2fg6", topicTitle: "Combining Transformations 69", difficulty: "Challenge", questionText: "The line \\(y = x\\) is transformed by \\(y = f(x) \\to y = 2f(x - 1) + 3\\). Find the new equation.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply.", workingLatex: "y = 2(x - 1) + 3 = 2x + 1", explanation: "" } ], finalAnswer: "\\(y = 2x + 1\\)." } },
  { id: "y2fg6-070", topicRef: "y2fg6", topicTitle: "Combining Transformations 70", difficulty: "Challenge", questionText: "\\(y = x^2\\) is transformed by \\(y = f(x) \\to y = f(2x) - 3\\). Find the new equation.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply.", workingLatex: "y = (2x)^2 - 3 = 4x^2 - 3", explanation: "" } ], finalAnswer: "\\(y = 4x^2 - 3\\)." } },
  { id: "y2fg6-071", topicRef: "y2fg6", topicTitle: "Combining Transformations 71", difficulty: "Challenge", questionText: "A parabola has vertex \\((-2, 5)\\) and passes through \\((0, 1)\\). Express as a transformation of \\(y = x^2\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "\\(y = a(x + 2)^2 + 5\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Substitute \\((0, 1)\\).", workingLatex: "1 = 4a + 5 \\Rightarrow a = -1", explanation: "" } ], finalAnswer: "\\(y = -(x + 2)^2 + 5\\) — reflect, left 2, up 5." } },
  // ── Extended batch (72–141) ────
  { id: "y2fg6-072", topicRef: "y2fg6", topicTitle: "Combining Transformations 72", difficulty: "Foundation", questionText: "\\((2, -3)\\) lies on \\(y = f(x)\\). Image on \\(y = f(x) - 4\\)?", marks: 1, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Subtract 4.", workingLatex: "", explanation: "" } ], finalAnswer: "\\((2, -7)\\)." } },
  { id: "y2fg6-073", topicRef: "y2fg6", topicTitle: "Combining Transformations 73", difficulty: "Foundation", questionText: "Image of \\((5, 2)\\) on \\(y = f(x + 2)\\)?", marks: 1, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Shift x by \\(-2\\).", workingLatex: "", explanation: "" } ], finalAnswer: "\\((3, 2)\\)." } },
  { id: "y2fg6-074", topicRef: "y2fg6", topicTitle: "Combining Transformations 74", difficulty: "Foundation", questionText: "Image of \\((2, 4)\\) on \\(y = -f(x)\\)?", marks: 1, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Negate y.", workingLatex: "", explanation: "" } ], finalAnswer: "\\((2, -4)\\)." } },
  { id: "y2fg6-075", topicRef: "y2fg6", topicTitle: "Combining Transformations 75", difficulty: "Challenge", questionText: "The point \\(P(6, -8)\\) lies on the curve \\(y = f(x)\\). (a) The point \\(P\\) is mapped to the point \\(Q(-3, 12)\\) under the transformation \\(y = a\\,f(bx)\\). Find the values of the constants \\(a\\) and \\(b\\). (b) Using these values of \\(a\\) and \\(b\\), the curve \\(y = a\\,f(bx)\\) is then translated by \\(\\begin{pmatrix} 0 \\\\ 5 \\end{pmatrix}\\). Find the image of \\(P\\) on this final curve. (c) The point \\(R\\) on \\(y = f(x)\\) is mapped to \\((10, 0)\\) on \\(y = a\\,f(bx)\\). Find the coordinates of \\(R\\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["transformations", "image", "find-original", "parameter"], workedSolution: { steps: [ { stepNumber: 1, description: "Relate the x-coordinates through the stretch b.", workingLatex: "y = f(bx): \\ x' = \\tfrac{x}{b} \\Rightarrow -3 = \\tfrac{6}{b}", explanation: "Replacing \\(x\\) by \\(bx\\) is a horizontal stretch of factor \\(\\tfrac1b\\), so an original \\(x\\)-value is divided by \\(b\\). A common slip is to multiply by \\(b\\) instead." }, { stepNumber: 2, description: "Solve for b.", workingLatex: "b = \\tfrac{6}{-3} = -2", explanation: "The negative value tells us the horizontal change also includes a reflection in the \\(y\\)-axis." }, { stepNumber: 3, description: "Relate the y-coordinates through the stretch a.", workingLatex: "y' = a y \\Rightarrow 12 = a(-8) \\Rightarrow a = -\\tfrac{3}{2}", explanation: "The vertical factor multiplies the \\(y\\)-coordinate. The negative \\(a\\) means a reflection in the \\(x\\)-axis as well as a stretch of factor \\(\\tfrac32\\)." }, { stepNumber: 4, description: "State the image of P on y = a f(bx).", workingLatex: "P(6, -8) \\to (-3, 12)", explanation: "This is the given mapping with \\(a = -\\tfrac32,\\ b = -2\\); it is the starting point for part (b)." }, { stepNumber: 5, description: "Apply the translation up 5.", workingLatex: "(-3, 12) \\to (-3, 12 + 5) = (-3, 17)", explanation: "A translation by \\(\\begin{pmatrix} 0 \\\\ 5 \\end{pmatrix}\\) adds 5 to the \\(y\\)-coordinate only; the \\(x\\)-coordinate is unchanged." }, { stepNumber: 6, description: "Find the x-coordinate of R from the image x = 10.", workingLatex: "10 = \\tfrac{x_R}{b} = \\tfrac{x_R}{-2} \\Rightarrow x_R = -20", explanation: "Reverse the horizontal rule: the image \\(x\\)-value is the original divided by \\(b\\), so the original is \\(b\\) times the image." }, { stepNumber: 7, description: "Find the y-coordinate of R from the image y = 0.", workingLatex: "0 = a\\,y_R = -\\tfrac{3}{2}\\,y_R \\Rightarrow y_R = 0", explanation: "Since \\(a \\neq 0\\), the only way the image \\(y\\)-value is 0 is if the original \\(y\\)-value is 0." } ], finalAnswer: "(a) \\(a = -\\tfrac{3}{2},\\ b = -2\\). (b) \\((-3,\\ 17)\\). (c) \\(R = (-20,\\ 0)\\)." } },
  { id: "y2fg6-076", topicRef: "y2fg6", topicTitle: "Combining Transformations 76", difficulty: "Standard", questionText: "Image of \\((2, 3)\\) on \\(y = f(\\tfrac{x}{3})\\)?", marks: 2, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Horizontal stretch factor 3.", workingLatex: "", explanation: "" } ], finalAnswer: "\\((6, 3)\\)." } },
  { id: "y2fg6-077", topicRef: "y2fg6", topicTitle: "Combining Transformations 77", difficulty: "Challenge", questionText: "Image of \\((-1, 2)\\) on \\(y = 4f(2x - 2)\\)?", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor inside: \\(f(2(x - 1))\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "Steps.", workingLatex: "(-1, 2) \\to (0, 2) \\to (0, 2) \\to (0, 8)", explanation: "Wait: shift right 1 then halve \\(x\\) by ×1/2: \\((-1, 2) \\to (0, 2) \\to (0, 2)\\)." } ], finalAnswer: "\\((0, 8)\\)." } },
  { id: "y2fg6-078", topicRef: "y2fg6", topicTitle: "Combining Transformations 78", difficulty: "Foundation", questionText: "Describe \\(y = f(x + 3) - 5\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "", explanation: "" } ], finalAnswer: "Left 3, then down 5." } },
  { id: "y2fg6-079", topicRef: "y2fg6", topicTitle: "Combining Transformations 79", difficulty: "Challenge", questionText: "A curve has equation \\(y = g(x)\\). After the transformation \\(y = 4 - 2\\,g(x - 3)\\) is applied, the resulting curve passes through the point \\((7, -6)\\) and has a minimum point at \\((1, 4)\\). (a) Find the coordinates of the point on the original curve \\(y = g(x)\\) that maps to \\((7, -6)\\). (b) The minimum point of \\(y = 4 - 2g(x-3)\\) is at \\((1, 4)\\). Find the coordinates of the corresponding stationary point on \\(y = g(x)\\), and state whether it is a maximum or a minimum. (c) Explain why the transformation turns a maximum of \\(g\\) into a minimum of the new curve.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["transformations", "find-original", "image", "order"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the inverse mapping for the x-coordinate.", workingLatex: "y = g(x - 3): \\ x_{\\text{new}} = x_{\\text{old}} + 3", explanation: "Replacing \\(x\\) with \\(x - 3\\) translates the curve right by 3, so an original \\(x\\)-value gains 3. To go back, subtract 3." }, { stepNumber: 2, description: "Set up the inverse mapping for the y-coordinate.", workingLatex: "y_{\\text{new}} = 4 - 2\\,y_{\\text{old}} \\Rightarrow y_{\\text{old}} = \\tfrac{4 - y_{\\text{new}}}{2}", explanation: "The output is reflected in the \\(x\\)-axis (the \\(-2\\)), stretched by 2, then shifted up 4. Rearranging gives the original \\(y\\)." }, { stepNumber: 3, description: "Reverse-map the point (7, -6) for part (a).", workingLatex: "x_{\\text{old}} = 7 - 3 = 4, \\quad y_{\\text{old}} = \\tfrac{4 - (-6)}{2} = 5", explanation: "Subtract 3 from the \\(x\\)-coordinate and apply the \\(y\\) formula. So \\((7,-6)\\) is the image of \\((4, 5)\\) on \\(g\\)." }, { stepNumber: 4, description: "Reverse-map the x-coordinate of the minimum (1, 4).", workingLatex: "x_{\\text{old}} = 1 - 3 = -2", explanation: "Same horizontal rule: undo the right-3 translation by subtracting 3." }, { stepNumber: 5, description: "Reverse-map the y-coordinate of the minimum (1, 4).", workingLatex: "y_{\\text{old}} = \\tfrac{4 - 4}{2} = 0", explanation: "Apply the \\(y\\) formula to \\(y_{\\text{new}} = 4\\), giving \\(y_{\\text{old}} = 0\\)." }, { stepNumber: 6, description: "Classify the stationary point on g.", workingLatex: "y_{\\text{new}} = 4 - 2\\,y_{\\text{old}}: \\ \\text{negative coefficient} \\Rightarrow \\text{min} \\leftrightarrow \\text{max}", explanation: "Because \\(y_{\\text{old}}\\) is multiplied by the negative number \\(-2\\), large \\(y_{\\text{old}}\\) gives small \\(y_{\\text{new}}\\). A minimum of the new curve must come from a maximum of \\(g\\)." }, { stepNumber: 7, description: "State the corresponding point and its nature.", workingLatex: "(-2, 0) \\text{ is a maximum of } y = g(x)", explanation: "The reflection swaps the type of turning point; the vertical stretch and translations do not change which point is highest." } ], finalAnswer: "(a) \\((4,\\ 5)\\). (b) \\((-2,\\ 0)\\), which is a maximum of \\(y = g(x)\\). (c) The factor \\(-2\\) reflects outputs in the \\(x\\)-axis, so the highest point of \\(g\\) becomes the lowest point of the new curve, turning a maximum into a minimum." } },
  { id: "y2fg6-080", topicRef: "y2fg6", topicTitle: "Combining Transformations 80", difficulty: "Challenge", questionText: "Describe \\(y = f(-x - 2)\\) as a sequence of transformations from \\(f(x)\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor.", workingLatex: "f(-(x + 2))", explanation: "" } ], finalAnswer: "Left 2, then reflect in y-axis." } },
  { id: "y2fg6-081", topicRef: "y2fg6", topicTitle: "Combining Transformations 81", difficulty: "Challenge", questionText: "Describe \\(y = 2f(3(x + 1))\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Inside first, then outside.", workingLatex: "", explanation: "" } ], finalAnswer: "Left 1, horizontal stretch factor \\(\\tfrac{1}{3}\\), vertical stretch ×2." } },
  { id: "y2fg6-082", topicRef: "y2fg6", topicTitle: "Combining Transformations 82", difficulty: "Standard", questionText: "Start with \\(y = \\sin x\\); stretch vertically ×4 then translate left \\(\\tfrac{\\pi}{2}\\). Write the equation.", marks: 2, examStyle: true, yearCreated: 2026, tags: ["transformations", "trig"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "y = 4\\sin(x + \\tfrac{\\pi}{2}) = 4\\cos x", explanation: "" } ], finalAnswer: "\\(y = 4\\cos x\\)." } },
  { id: "y2fg6-083", topicRef: "y2fg6", topicTitle: "Combining Transformations 83", difficulty: "Foundation", questionText: "Stretch \\(y = x^2\\) horizontally by factor 2. New equation?", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Replace \\(x\\) by \\(\\tfrac{x}{2}\\).", workingLatex: "", explanation: "" } ], finalAnswer: "\\(y = \\tfrac{x^2}{4}\\)." } },
  { id: "y2fg6-084", topicRef: "y2fg6", topicTitle: "Combining Transformations 84", difficulty: "Foundation", questionText: "State the vertex of \\(y = -(x - 2)^2 + 5\\) and the transformations from \\(y = x^2\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "", explanation: "" } ], finalAnswer: "Vertex \\((2, 5)\\); right 2, reflect in x-axis, up 5." } },
  { id: "y2fg6-085", topicRef: "y2fg6", topicTitle: "Combining Transformations 85", difficulty: "Challenge", questionText: "The curve \\(C\\) has equation \\(y = 3\\sin\\!\\left(4x - \\tfrac{\\pi}{2}\\right) + 1\\). (a) By writing the argument as \\(4\\left(x - \\tfrac{\\pi}{8}\\right)\\), describe the sequence of four transformations mapping \\(y = \\sin x\\) onto \\(C\\). (b) State the period and the exact maximum and minimum values of \\(y\\) on \\(C\\). (c) Find the smallest positive value of \\(x\\) at which \\(C\\) attains its maximum value.", marks: 7, examStyle: true, yearCreated: 2026, tags: ["transformations", "trig", "composite-argument", "period"], workedSolution: { steps: [ { stepNumber: 1, description: "Factorise the argument of the sine.", workingLatex: "y = 3\\sin\\big(4(x - \\tfrac{\\pi}{8})\\big) + 1", explanation: "Factor the coefficient 4 from \\(4x - \\tfrac{\\pi}{2}\\): \\(4x - \\tfrac{\\pi}{2} = 4(x - \\tfrac{\\pi}{8})\\). This separates the horizontal stretch from the horizontal shift." }, { stepNumber: 2, description: "Identify the horizontal stretch.", workingLatex: "\\sin x \\to \\sin(4x): \\text{ stretch in } x \\text{ factor } \\tfrac{1}{4}", explanation: "Replacing \\(x\\) by \\(4x\\) compresses horizontally with scale factor \\(\\tfrac14\\), so the period shortens." }, { stepNumber: 3, description: "Identify the horizontal translation.", workingLatex: "\\sin(4x) \\to \\sin(4(x - \\tfrac{\\pi}{8})): \\text{ translation } \\begin{pmatrix} \\tfrac{\\pi}{8} \\\\ 0 \\end{pmatrix}", explanation: "The bracket \\((x - \\tfrac{\\pi}{8})\\) shifts right by \\(\\tfrac{\\pi}{8}\\). Reading \\(\\tfrac{\\pi}{2}\\) as the shift, before factorising, is the standard mistake." }, { stepNumber: 4, description: "Identify the vertical stretch and translation.", workingLatex: "\\sin(4(x - \\tfrac{\\pi}{8})) \\to 3\\sin(\\ldots) \\to 3\\sin(\\ldots) + 1", explanation: "Multiplying by 3 is a vertical stretch of factor 3; adding 1 translates up by 1. The stretch must precede the \\(+1\\)." }, { stepNumber: 5, description: "State the period.", workingLatex: "\\text{period} = \\tfrac{2\\pi}{4} = \\tfrac{\\pi}{2}", explanation: "The horizontal stretch factor \\(\\tfrac14\\) divides the standard period \\(2\\pi\\) by 4." }, { stepNumber: 6, description: "State the maximum and minimum values.", workingLatex: "\\sin \\in [-1, 1] \\Rightarrow y \\in [3(-1)+1,\\ 3(1)+1] = [-2, 4]", explanation: "The \\(\\sin\\) part ranges over \\([-1,1]\\); the stretch by 3 makes it \\([-3,3]\\); the \\(+1\\) shifts to \\([-2,4]\\)." }, { stepNumber: 7, description: "Find the first maximum.", workingLatex: "4x - \\tfrac{\\pi}{2} = \\tfrac{\\pi}{2} \\Rightarrow 4x = \\pi \\Rightarrow x = \\tfrac{\\pi}{4}", explanation: "The maximum of \\(\\sin\\) occurs when its argument is \\(\\tfrac{\\pi}{2}\\) (plus multiples of \\(2\\pi\\)). The smallest positive solution is \\(x = \\tfrac{\\pi}{4}\\)." } ], finalAnswer: "(a) Horizontal stretch factor \\(\\tfrac{1}{4}\\), then translation \\(\\begin{pmatrix} \\tfrac{\\pi}{8} \\\\ 0 \\end{pmatrix}\\), then vertical stretch factor 3, then translation \\(\\begin{pmatrix} 0 \\\\ 1 \\end{pmatrix}\\). (b) Period \\(\\tfrac{\\pi}{2}\\); maximum \\(y = 4\\), minimum \\(y = -2\\). (c) \\(x = \\tfrac{\\pi}{4}\\)." } },
  { id: "y2fg6-086", topicRef: "y2fg6", topicTitle: "Combining Transformations 86", difficulty: "Standard", questionText: "State the amplitude and period of \\(y = 3\\cos(\\tfrac{x}{2})\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "", explanation: "" } ], finalAnswer: "Amplitude 3; period \\(4\\pi\\)." } },
  { id: "y2fg6-087", topicRef: "y2fg6", topicTitle: "Combining Transformations 87", difficulty: "Challenge", questionText: "Max of \\(\\cos x\\) is at \\((0, 1)\\). Find the image of this max on \\(y = 2\\cos(x - \\pi)\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["trig", "transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Shift right \\(\\pi\\), stretch ×2.", workingLatex: "(0, 1) \\to (\\pi, 1) \\to (\\pi, 2)", explanation: "" } ], finalAnswer: "\\((\\pi, 2)\\)." } },
  { id: "y2fg6-088", topicRef: "y2fg6", topicTitle: "Combining Transformations 88", difficulty: "Standard", questionText: "Translate \\(y = 2^x\\) up so it passes through \\((3, 8)\\) — state the equation. (No vertical stretch.)", marks: 2, examStyle: true, yearCreated: 2026, tags: ["exp"], workedSolution: { steps: [ { stepNumber: 1, description: "At \\(x = 3\\), \\(2^3 = 8\\), so no shift needed.", workingLatex: "", explanation: "" } ], finalAnswer: "\\(y = 2^x\\) (no translation needed)." } },
  { id: "y2fg6-089", topicRef: "y2fg6", topicTitle: "Combining Transformations 89", difficulty: "Challenge", questionText: "A curve \\(C\\) is obtained from \\(y = \\ln x\\) by the following chain of transformations, in order: a stretch parallel to the \\(x\\)-axis by scale factor \\(\\tfrac{1}{3}\\), then a translation by \\(\\begin{pmatrix} 2 \\\\ 0 \\end{pmatrix}\\), then a vertical stretch by scale factor \\(2\\), then a translation by \\(\\begin{pmatrix} 0 \\\\ -1 \\end{pmatrix}\\). (a) Find the equation of \\(C\\), simplifying the argument of the logarithm. (b) State the equation of the vertical asymptote of \\(C\\). (c) Find the exact \\(x\\)-coordinate of the point where \\(C\\) crosses the \\(x\\)-axis.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["transformations", "log", "order", "composite-argument"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply the horizontal stretch by factor 1/3.", workingLatex: "y = \\ln x \\to y = \\ln(3x)", explanation: "A horizontal stretch of factor \\(\\tfrac13\\) replaces \\(x\\) with \\(3x\\); the reciprocal of the scale factor goes inside." }, { stepNumber: 2, description: "Apply the translation right by 2.", workingLatex: "y = \\ln(3x) \\to y = \\ln(3(x - 2)) = \\ln(3x - 6)", explanation: "Translating right by 2 replaces \\(x\\) with \\(x - 2\\) inside the function: \\(3(x-2) = 3x - 6\\). Forgetting to apply the shift inside the \\(3x\\) is the usual error." }, { stepNumber: 3, description: "Apply the vertical stretch by factor 2.", workingLatex: "y = \\ln(3x - 6) \\to y = 2\\ln(3x - 6)", explanation: "A vertical stretch of factor 2 multiplies the whole output by 2." }, { stepNumber: 4, description: "Apply the translation down 1.", workingLatex: "y = 2\\ln(3x - 6) - 1", explanation: "A translation by \\(\\begin{pmatrix} 0 \\\\ -1 \\end{pmatrix}\\) subtracts 1 from the whole expression, after the stretch." }, { stepNumber: 5, description: "Find the vertical asymptote.", workingLatex: "3x - 6 = 0 \\Rightarrow x = 2", explanation: "A logarithm has a vertical asymptote where its argument is 0. The original asymptote \\(x = 0\\) maps under the stretch and shift to \\(x = 2\\)." }, { stepNumber: 6, description: "Set y = 0 to find the x-intercept.", workingLatex: "2\\ln(3x - 6) - 1 = 0 \\Rightarrow \\ln(3x - 6) = \\tfrac{1}{2}", explanation: "The curve meets the \\(x\\)-axis where \\(y = 0\\). Isolate the logarithm before exponentiating." }, { stepNumber: 7, description: "Solve for x by exponentiating.", workingLatex: "3x - 6 = e^{1/2} \\Rightarrow x = 2 + \\tfrac{e^{1/2}}{3}", explanation: "Apply \\(e^{(\\cdot)}\\) to both sides, then rearrange. Keep the answer exact: \\(e^{1/2} = \\sqrt{e}\\), so \\(x = 2 + \\tfrac{\\sqrt{e}}{3}\\)." } ], finalAnswer: "(a) \\(y = 2\\ln(3x - 6) - 1\\). (b) \\(x = 2\\). (c) \\(x = 2 + \\tfrac{\\sqrt{e}}{3}\\) (equivalently \\(2 + \\tfrac{e^{1/2}}{3}\\))." } },
  { id: "y2fg6-090", topicRef: "y2fg6", topicTitle: "Combining Transformations 90", difficulty: "Standard", questionText: "Describe \\(y = e^{-x} + 4\\) from \\(y = e^x\\).", marks: 2, examStyle: true, yearCreated: 2026, tags: ["exp"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "", explanation: "" } ], finalAnswer: "Reflect in y-axis, then up 4." } },
  { id: "y2fg6-091", topicRef: "y2fg6", topicTitle: "Combining Transformations 91", difficulty: "Standard", questionText: "\\((0, 1)\\) on \\(y = e^x\\). Find its image on \\(y = e^{x - 2} + 3\\).", marks: 2, examStyle: true, yearCreated: 2026, tags: ["exp", "transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "(0, 1) \\to (2, 1) \\to (2, 4)", explanation: "" } ], finalAnswer: "\\((2, 4)\\)." } },
  { id: "y2fg6-092", topicRef: "y2fg6", topicTitle: "Combining Transformations 92", difficulty: "Foundation", questionText: "Find the asymptotes of \\(y = \\tfrac{2}{x - 3} + 1\\).", marks: 2, examStyle: true, yearCreated: 2026, tags: ["reciprocal"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "", explanation: "" } ], finalAnswer: "\\(x = 3, y = 1\\)." } },
  { id: "y2fg6-093", topicRef: "y2fg6", topicTitle: "Combining Transformations 93", difficulty: "Challenge", questionText: "A transformation of \\(y = \\tfrac{1}{x}\\) has asymptotes \\(x = -2, y = 5\\) and passes through \\((0, 4)\\). Find the equation.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["reciprocal"], workedSolution: { steps: [ { stepNumber: 1, description: "Form.", workingLatex: "y = \\tfrac{a}{x + 2} + 5", explanation: "" }, { stepNumber: 2, description: "At \\((0, 4)\\).", workingLatex: "4 = \\tfrac{a}{2} + 5 \\Rightarrow a = -2", explanation: "" } ], finalAnswer: "\\(y = -\\tfrac{2}{x + 2} + 5\\)." } },
  { id: "y2fg6-094", topicRef: "y2fg6", topicTitle: "Combining Transformations 94", difficulty: "Challenge", questionText: "The function \\(f\\) has range \\([2, 7]\\). (a) State the range of \\(y = 3 - 2f\\big(\\tfrac{1}{2}x\\big)\\), justifying which transformations affect the range. (b) The curve \\(y = f(x)\\) has a single maximum at the point \\((4, 7)\\). State the coordinates of the corresponding turning point on \\(y = 3 - 2f\\big(\\tfrac{1}{2}x\\big)\\) and say whether it is a maximum or a minimum.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["transformations", "range", "image", "order"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify which transformations act on the output (range) and which act on the input.", workingLatex: "y = 3 - 2f\\big(\\tfrac{1}{2}x\\big)", explanation: "The horizontal stretch \\(\\tfrac{1}{2}x\\) acts on the input, so it does not change the set of \\(y\\)-values at all. Only the \\(\\times(-2)\\) and \\(+3\\) outside \\(f\\) affect the range. A common slip is to try to scale the range by the horizontal stretch factor." }, { stepNumber: 2, description: "Apply the vertical stretch by factor \\(-2\\) to the range \\([2,7]\\).", workingLatex: "-2 \\times 2 = -4, \\qquad -2 \\times 7 = -14", explanation: "Multiplying by a negative number reverses the order of the endpoints, so the image set is \\([-14, -4]\\), not \\([-4,-14]\\). Always re-order so the smaller value is written first." }, { stepNumber: 3, description: "Apply the vertical translation \\(+3\\) to both endpoints.", workingLatex: "-14 + 3 = -11, \\qquad -4 + 3 = -1", explanation: "Translation shifts every output by the same amount, so the width of the interval is unchanged; only its position moves." }, { stepNumber: 4, description: "State the range.", workingLatex: "\\text{range} = [-11, -1]", explanation: "This is the range of \\(y = 3 - 2f\\big(\\tfrac{1}{2}x\\big)\\); the horizontal stretch played no part, confirming step 1." }, { stepNumber: 5, description: "Transform the maximum point \\((4,7)\\). Apply the horizontal stretch first to the \\(x\\)-coordinate.", workingLatex: "f\\big(\\tfrac{1}{2}x\\big): \\ \\tfrac{1}{2}x = 4 \\Rightarrow x = 8", explanation: "Replacing \\(x\\) by \\(\\tfrac{1}{2}x\\) is a horizontal stretch of factor \\(2\\), so the input \\(x\\)-value doubles. The \\(y\\)-coordinate is untouched by an input transformation." }, { stepNumber: 6, description: "Apply \\(\\times(-2)\\) then \\(+3\\) to the \\(y\\)-coordinate \\(7\\).", workingLatex: "-2 \\times 7 + 3 = -14 + 3 = -11", explanation: "Because the curve is multiplied by a negative factor, the original maximum becomes a minimum: the curve is flipped vertically. The point \\((8,-11)\\) is the lowest point of the new range, agreeing with step 4." } ], finalAnswer: "(a) Range \\(= [-11, -1]\\); the horizontal stretch does not affect the range. (b) Turning point \\((8, -11)\\), which is a minimum." } },
  { id: "y2fg6-095", topicRef: "y2fg6", topicTitle: "Combining Transformations 95", difficulty: "Foundation", questionText: "\\(f\\) has min \\(-1\\). Min of \\(y = 2f(x) + 5\\)?", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "", explanation: "" } ], finalAnswer: "3." } },
  { id: "y2fg6-096", topicRef: "y2fg6", topicTitle: "Combining Transformations 96", difficulty: "Standard", questionText: "\\(f\\) has range \\([-4, 6]\\). Range of \\(y = f(3x) - 1\\)?", marks: 2, examStyle: true, yearCreated: 2026, tags: ["range"], workedSolution: { steps: [ { stepNumber: 1, description: "Horizontal stretch doesn't affect range; shift.", workingLatex: "", explanation: "" } ], finalAnswer: "\\([-5, 5]\\)." } },
  { id: "y2fg6-097", topicRef: "y2fg6", topicTitle: "Combining Transformations 97", difficulty: "Standard", questionText: "Period of \\(y = \\sin(3x - \\pi)\\)?", marks: 2, examStyle: false, yearCreated: 2026, tags: ["period"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "\\tfrac{2\\pi}{3}", explanation: "" } ], finalAnswer: "\\(\\tfrac{2\\pi}{3}\\)." } },
  { id: "y2fg6-098", topicRef: "y2fg6", topicTitle: "Combining Transformations 98", difficulty: "Challenge", questionText: "The function \\(f\\) has exactly three roots, at \\(x = 1\\), \\(x = 3\\) and \\(x = 5\\), and \\(f(0) = 12\\). (a) By writing the argument in the form \\(f(a(x-b))\\), find all roots of \\(y = f(2x - 4)\\). (b) Find all roots of \\(y = 3f(2x - 4)\\) and state its \\(y\\)-intercept. (c) Explain why \\(y = f(2x-4) + 1\\) need not have the same number of roots as \\(f\\).", marks: 7, examStyle: true, yearCreated: 2026, tags: ["transformations", "roots", "composite-argument", "order"], workedSolution: { steps: [ { stepNumber: 1, description: "Factorise the argument to read off the transformations.", workingLatex: "f(2x - 4) = f\\big(2(x - 2)\\big)", explanation: "Factor the \\(2\\) out of the bracket. This is a horizontal stretch of factor \\(\\tfrac{1}{2}\\) followed by a translation \\(2\\) to the right. A common error is to read \\(-4\\) as a shift of \\(4\\); you must factorise first." }, { stepNumber: 2, description: "A root occurs where the argument equals an original root \\(r\\). Solve \\(2x - 4 = r\\).", workingLatex: "2x - 4 = r \\Rightarrow x = \\tfrac{r + 4}{2}", explanation: "The curve \\(f\\) is zero at \\(x = r\\); the transformed curve is zero when its argument hits the same \\(r\\). Solving for \\(x\\) gives the new root location." }, { stepNumber: 3, description: "Substitute the three original roots \\(r = 1, 3, 5\\).", workingLatex: "x = \\tfrac{5}{2}, \\quad x = \\tfrac{7}{2}, \\quad x = \\tfrac{9}{2}", explanation: "Each root moves to half its distance from \\(x=2\\): the roots compress towards \\(x=2\\) and shift. The roots stay in the same left-to-right order." }, { stepNumber: 4, description: "Roots of \\(y = 3f(2x - 4)\\).", workingLatex: "3f(2x-4) = 0 \\iff f(2x-4) = 0", explanation: "A vertical stretch by factor \\(3\\) multiplies every \\(y\\)-value by \\(3\\); a zero stays a zero. So the roots are unchanged from part (a)." }, { stepNumber: 5, description: "Find the \\(y\\)-intercept of \\(y = 3f(2x-4)\\) by setting \\(x = 0\\).", workingLatex: "3f(2\\cdot 0 - 4) = 3f(-4)", explanation: "Setting \\(x=0\\) gives the argument \\(-4\\). But we are only told \\(f(0)=12\\), not \\(f(-4)\\). The intercept depends on a value of \\(f\\) we do not know." }, { stepNumber: 6, description: "State what can and cannot be determined.", workingLatex: "y\\text{-intercept} = 3f(-4) \\ \\text{(undetermined)}", explanation: "The horizontal stretch/translation moves \\(x=0\\) onto the argument \\(-4\\); since \\(f(-4)\\) is not given, the \\(y\\)-intercept cannot be evaluated. Recognising what data is missing is part of the challenge." }, { stepNumber: 7, description: "Explain the root count for \\(y = f(2x-4)+1\\).", workingLatex: "f(2x-4) + 1 = 0 \\iff f(2x-4) = -1", explanation: "Adding \\(1\\) raises the whole curve. Its roots are now where \\(f\\) equals \\(-1\\), not \\(0\\). Depending on the shape of \\(f\\), the line \\(y=-1\\) may cross the curve a different number of times, so the root count can change." } ], finalAnswer: "(a) Roots \\(x = \\tfrac{5}{2}, \\tfrac{7}{2}, \\tfrac{9}{2}\\). (b) Same roots \\(x = \\tfrac{5}{2}, \\tfrac{7}{2}, \\tfrac{9}{2}\\); the \\(y\\)-intercept is \\(3f(-4)\\), which cannot be evaluated from the given information. (c) Adding \\(1\\) shifts the curve up, so its roots occur where \\(f = -1\\); the horizontal line \\(y=-1\\) may meet the curve a different number of times, so the count can differ." } },
  { id: "y2fg6-099", topicRef: "y2fg6", topicTitle: "Combining Transformations 99", difficulty: "Standard", questionText: "\\(f\\) has turning point \\((2, -1)\\). Turning point of \\(y = 2f(x - 3) + 4\\)?", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply.", workingLatex: "(2, -1) \\to (5, -1) \\to (5, -2) \\to (5, 2)", explanation: "" } ], finalAnswer: "\\((5, 2)\\)." } },
  { id: "y2fg6-100", topicRef: "y2fg6", topicTitle: "Combining Transformations 100", difficulty: "Standard", questionText: "\\(f(3) = 4\\). Find \\(a\\) so \\(y = af(x)\\) passes through \\((3, 10)\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "4a = 10", explanation: "" } ], finalAnswer: "\\(a = \\tfrac{5}{2}\\)." } },
  { id: "y2fg6-101", topicRef: "y2fg6", topicTitle: "Combining Transformations 101", difficulty: "Challenge", questionText: "\\(f\\) has minimum value \\(-3\\). Find \\(k\\) so \\(y = f(x) + k\\) touches the x-axis.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Need min + k = 0.", workingLatex: "", explanation: "" } ], finalAnswer: "\\(k = 3\\)." } },
  { id: "y2fg6-102", topicRef: "y2fg6", topicTitle: "Combining Transformations 102", difficulty: "Challenge", questionText: "Starting from \\(y = x^2\\), the following transformations are applied in order: (i) a translation by \\(\\binom{3}{0}\\), (ii) a vertical stretch by factor \\(2\\), (iii) a reflection in the \\(x\\)-axis, (iv) a translation by \\(\\binom{0}{5}\\). (a) Find the equation of the resulting curve in the form \\(y = a(x-h)^2 + k\\). (b) State the coordinates of its vertex and whether it is a maximum or minimum. (c) Show that performing (ii) and (iii) in the opposite order gives the same final curve, but performing (i) after (iv) does not.", marks: 7, examStyle: true, yearCreated: 2026, tags: ["transformations", "order", "image", "composite-argument"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply (i): translate \\(y = x^2\\) by \\(\\binom{3}{0}\\).", workingLatex: "y = (x - 3)^2", explanation: "A translation \\(3\\) units right replaces \\(x\\) with \\(x-3\\). The sign is opposite to what many expect: moving right means subtracting inside the bracket." }, { stepNumber: 2, description: "Apply (ii): vertical stretch by factor \\(2\\).", workingLatex: "y = 2(x - 3)^2", explanation: "A vertical stretch multiplies the whole output by \\(2\\); every \\(y\\)-value doubles." }, { stepNumber: 3, description: "Apply (iii): reflect in the \\(x\\)-axis.", workingLatex: "y = -2(x - 3)^2", explanation: "Reflection in the \\(x\\)-axis multiplies the output by \\(-1\\), changing the sign of the leading coefficient." }, { stepNumber: 4, description: "Apply (iv): translate by \\(\\binom{0}{5}\\).", workingLatex: "y = -2(x - 3)^2 + 5", explanation: "A vertical translation adds \\(5\\) to the output. This is the final equation in completed-square form with \\(a=-2,\\ h=3,\\ k=5\\)." }, { stepNumber: 5, description: "Read off the vertex.", workingLatex: "y = -2(x-3)^2 + 5 \\Rightarrow \\text{vertex } (3, 5)", explanation: "The squared term is zero at \\(x = 3\\), giving \\(y = 5\\). Since \\(a = -2 < 0\\) the parabola opens downwards, so the vertex is a maximum." }, { stepNumber: 6, description: "Swap (ii) and (iii): reflect first, then stretch.", workingLatex: "y = (x-3)^2 \\xrightarrow{\\text{reflect}} -(x-3)^2 \\xrightarrow{\\times 2} -2(x-3)^2", explanation: "Both are output operations: multiplying by \\(-1\\) then by \\(2\\), or by \\(2\\) then by \\(-1\\), both give a factor of \\(-2\\). Multiplication of scalars commutes, so the order is irrelevant here." }, { stepNumber: 7, description: "Compare (i)-before-(iv) with (iv)-before-(i).", workingLatex: "(i)\\text{ then }(iv): \\ y=-2(x-3)^2+5; \\quad (iv)\\text{ then }(i): \\ \\text{shift up }5\\text{ then right }3", explanation: "A horizontal translation (i) and a vertical translation (iv) both act on different variables, so they actually still commute. The point of contrast is the reflection: doing the horizontal shift (i) after the reflection/stretch versus before changes the vertex \\(x\\)-coordinate only if combined with a horizontal scaling — here it does not, but doing (iv) before (iii) would: \\(-2[(x-3)^2+5] = -2(x-3)^2-10 \\neq -2(x-3)^2+5\\). So order matters whenever a translation crosses a stretch or reflection acting on the same variable." } ], finalAnswer: "(a) \\(y = -2(x - 3)^2 + 5\\). (b) Vertex \\((3, 5)\\), a maximum. (c) Swapping the vertical stretch and reflection both contribute a scalar factor whose product \\(-2\\) is order-independent, so the curve is unchanged; but a vertical translation must be applied after a vertical stretch/reflection, since e.g. \\(-2[(x-3)^2+5] = -2(x-3)^2 - 10 \\ne -2(x-3)^2 + 5\\)." } },
  { id: "y2fg6-103", topicRef: "y2fg6", topicTitle: "Combining Transformations 103", difficulty: "Challenge", questionText: "If \\(g(x) = 2f(x - 3)\\), express \\(g^{-1}(x)\\) in terms of \\(f^{-1}\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["transformations", "inverse"], workedSolution: { steps: [ { stepNumber: 1, description: "Let \\(y = 2f(x - 3)\\).", workingLatex: "f(x - 3) = \\tfrac{y}{2} \\Rightarrow x = f^{-1}(\\tfrac{y}{2}) + 3", explanation: "" } ], finalAnswer: "\\(g^{-1}(x) = f^{-1}(\\tfrac{x}{2}) + 3\\)." } },
  { id: "y2fg6-104", topicRef: "y2fg6", topicTitle: "Combining Transformations 104", difficulty: "Standard", questionText: "Find \\(a, b > 0\\) so that \\(y = a\\sin(bx)\\) has amplitude 5 and period \\(\\pi\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "\\tfrac{2\\pi}{b} = \\pi \\Rightarrow b = 2", explanation: "" } ], finalAnswer: "\\(a = 5, b = 2\\)." } },
  { id: "y2fg6-105", topicRef: "y2fg6", topicTitle: "Combining Transformations 105", difficulty: "Challenge", questionText: "Apply to \\(y = \\sqrt x\\): reflect in y-axis then stretch vertically ×3. Equation?", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "y = 3\\sqrt{-x}", explanation: "" } ], finalAnswer: "\\(y = 3\\sqrt{-x}\\) (domain \\(x \\le 0\\))." } },
  { id: "y2fg6-106", topicRef: "y2fg6", topicTitle: "Combining Transformations 106", difficulty: "Challenge", questionText: "\\(y = \\ln x\\) is transformed to \\(y = 2\\ln(x + 1) - 3\\). At which x does the transformed curve cross the x-axis?", marks: 3, examStyle: true, yearCreated: 2026, tags: ["log"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "2\\ln(x + 1) = 3 \\Rightarrow x + 1 = e^{3/2}", explanation: "" } ], finalAnswer: "\\(x = e^{3/2} - 1 \\approx 3.48\\)." } },
  { id: "y2fg6-107", topicRef: "y2fg6", topicTitle: "Combining Transformations 107", difficulty: "Standard", questionText: "Explain the difference between \\(y = 2f(x)\\) and \\(y = f(2x)\\), using a specific max point of \\(f\\) at \\((2, 3)\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "\\(2f(x)\\) stretches vertically: \\((2, 6)\\).", workingLatex: "", explanation: "" }, { stepNumber: 2, description: "\\(f(2x)\\) stretches horizontally: \\((1, 3)\\).", workingLatex: "", explanation: "" } ], finalAnswer: "\\(2f(x)\\): \\((2, 6)\\); \\(f(2x)\\): \\((1, 3)\\)." } },
  { id: "y2fg6-108", topicRef: "y2fg6", topicTitle: "Combining Transformations 108", difficulty: "Foundation", questionText: "Image of \\((a, b)\\) on \\(y = f(-x) + 5\\)?", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "", explanation: "" } ], finalAnswer: "\\((-a, b + 5)\\)." } },
  { id: "y2fg6-109", topicRef: "y2fg6", topicTitle: "Combining Transformations 109", difficulty: "Challenge", questionText: "Describe the mapping \\((x, y) \\to (2x - 1, \\tfrac{y + 3}{2})\\) in terms of transformations of \\(y = f(x)\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "If \\((x, y)\\) on \\(y = f(x)\\), we want \\((X, Y)\\) with \\(X = 2x - 1, Y = \\tfrac{y + 3}{2}\\).", workingLatex: "x = \\tfrac{X + 1}{2},\\; y = 2Y - 3", explanation: "" } ], finalAnswer: "New curve: \\(2Y - 3 = f(\\tfrac{X + 1}{2}) \\Rightarrow Y = \\tfrac{f(\\tfrac{X + 1}{2}) + 3}{2}\\)." } },
  { id: "y2fg6-110", topicRef: "y2fg6", topicTitle: "Combining Transformations 110", difficulty: "Challenge", questionText: "The function \\(f\\) has domain \\([-2, 6]\\) and range \\([0, 9]\\). Define \\(g(x) = 4 - f(3 - 2x)\\). (a) By writing the argument as \\(f\\big(-2(x - \\tfrac{3}{2})\\big)\\), describe fully the sequence of transformations mapping \\(f\\) to \\(g\\). (b) Find the domain and range of \\(g\\). (c) The point \\((6, 9)\\) lies on \\(y = f(x)\\). Find its image on \\(y = g(x)\\).", marks: 8, examStyle: true, yearCreated: 2026, tags: ["transformations", "domain", "range", "composite-argument", "image"], workedSolution: { steps: [ { stepNumber: 1, description: "Factorise the argument of \\(f\\).", workingLatex: "3 - 2x = -2\\big(x - \\tfrac{3}{2}\\big)", explanation: "Factor out the coefficient of \\(x\\), namely \\(-2\\). Inside-bracket transformations only read correctly once the \\(x\\)-coefficient is factored out." }, { stepNumber: 2, description: "Describe the input transformations.", workingLatex: "f\\big(-2(x - \\tfrac{3}{2})\\big)", explanation: "The factor \\(-2\\) gives a horizontal stretch of factor \\(\\tfrac{1}{2}\\) together with a reflection in the \\(y\\)-axis; the \\(-\\tfrac{3}{2}\\) gives a translation \\(\\tfrac{3}{2}\\) to the right. Input transformations are applied in the reverse of the usual reading order." }, { stepNumber: 3, description: "Describe the output transformations \\(4 - f(\\cdots)\\).", workingLatex: "g = -f(\\cdots) + 4", explanation: "The \\(-1\\) is a reflection in the \\(x\\)-axis and the \\(+4\\) is a vertical translation up \\(4\\)." }, { stepNumber: 4, description: "Find the domain of \\(g\\): require the argument to lie in the domain of \\(f\\).", workingLatex: "-2 \\le 3 - 2x \\le 6", explanation: "The argument \\(3-2x\\) must be a value where \\(f\\) is defined, i.e. inside \\([-2,6]\\)." }, { stepNumber: 5, description: "Solve the inequality for \\(x\\).", workingLatex: "-2 \\le 3 - 2x \\le 6 \\Rightarrow -5 \\le -2x \\le 3 \\Rightarrow -\\tfrac{3}{2} \\le x \\le \\tfrac{5}{2}", explanation: "Dividing by \\(-2\\) reverses both inequality signs; this is the step where sign errors are most common. The domain of \\(g\\) is \\([-\\tfrac{3}{2}, \\tfrac{5}{2}]\\)." }, { stepNumber: 6, description: "Find the range of \\(g\\) by transforming the range \\([0,9]\\) of \\(f\\).", workingLatex: "-[0, 9] = [-9, 0]; \\quad [-9, 0] + 4 = [-5, 4]", explanation: "Only the output operations \\(-1\\) and \\(+4\\) change the range; the horizontal stretch and reflection do not. Reflecting negates and reverses the endpoints, then \\(+4\\) shifts up." }, { stepNumber: 7, description: "Transform the point \\((6, 9)\\): handle the \\(x\\)-coordinate via the argument.", workingLatex: "3 - 2x = 6 \\Rightarrow x = -\\tfrac{3}{2}", explanation: "The image point has the \\(x\\)-value for which the argument equals the original \\(x\\)-coordinate \\(6\\). Solving \\(3-2x=6\\) gives \\(x=-\\tfrac{3}{2}\\)." }, { stepNumber: 8, description: "Transform the \\(y\\)-coordinate \\(9\\).", workingLatex: "g = -9 + 4 = -5", explanation: "Apply the output transformations to \\(y=9\\): reflect to \\(-9\\), then add \\(4\\) to get \\(-5\\). The image point is \\((-\\tfrac{3}{2}, -5)\\), consistent with the endpoints of the domain and range found above." } ], finalAnswer: "(a) Horizontal stretch factor \\(\\tfrac{1}{2}\\) and reflection in the \\(y\\)-axis, then translation \\(\\tfrac{3}{2}\\) right, then reflection in the \\(x\\)-axis, then translation \\(4\\) up. (b) Domain \\([-\\tfrac{3}{2}, \\tfrac{5}{2}]\\), range \\([-5, 4]\\). (c) Image of \\((6,9)\\) is \\((-\\tfrac{3}{2}, -5)\\)." } },
  { id: "y2fg6-111", topicRef: "y2fg6", topicTitle: "Combining Transformations 111", difficulty: "Challenge", questionText: "A transformation of \\(y = x^2\\) has vertex \\((2, -3)\\) and passes through \\((0, 5)\\). State the equation.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "\\(y = a(x - 2)^2 - 3\\).", workingLatex: "5 = 4a - 3 \\Rightarrow a = 2", explanation: "" } ], finalAnswer: "\\(y = 2(x - 2)^2 - 3\\)." } },
  { id: "y2fg6-112", topicRef: "y2fg6", topicTitle: "Combining Transformations 112", difficulty: "Challenge", questionText: "Determine \\(b, c\\) for \\(y = (x + b)^2 + c\\) given its minimum is at \\((-2, -9)\\). Verify it passes through \\((1, 0)\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "b = 2, c = -9", explanation: "" }, { stepNumber: 2, description: "Check.", workingLatex: "(1 + 2)^2 - 9 = 0 ✓", explanation: "" } ], finalAnswer: "\\(b = 2, c = -9\\)." } },
  { id: "y2fg6-113", topicRef: "y2fg6", topicTitle: "Combining Transformations 113", difficulty: "Standard", questionText: "Find amplitude, period, and reflection for \\(y = -2\\sin(\\tfrac{\\pi x}{3})\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "", explanation: "" } ], finalAnswer: "Amplitude 2; period 6; reflection in x-axis." } },
  { id: "y2fg6-114", topicRef: "y2fg6", topicTitle: "Combining Transformations 114", difficulty: "Standard", questionText: "\\(f\\) has maximum \\((1, 5)\\). What kind of turning point is this on \\(y = -f(x)\\)?", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Reflecting in x-axis swaps max/min.", workingLatex: "", explanation: "" } ], finalAnswer: "Minimum at \\((1, -5)\\)." } },
  { id: "y2fg6-115", topicRef: "y2fg6", topicTitle: "Combining Transformations 115", difficulty: "Challenge", questionText: "The curve \\(y = f(x)\\) has a horizontal asymptote \\(y = 2\\) and a vertical asymptote \\(x = -1\\), and passes through \\((0, 5)\\). The curve \\(y = g(x)\\) is obtained by reflecting \\(y = f(x)\\) in the \\(x\\)-axis, then stretching vertically by factor \\(3\\), then translating by \\(\\binom{-4}{1}\\). (a) Write \\(g\\) in terms of \\(f\\). (b) State the equations of both asymptotes of \\(y = g(x)\\). (c) Find the \\(y\\)-coordinate of the point on \\(y = g(x)\\) whose \\(x\\)-coordinate is \\(-4\\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["transformations", "asymptotes", "order", "image"], workedSolution: { steps: [ { stepNumber: 1, description: "Build \\(g\\) one transformation at a time. Start with the reflection in the \\(x\\)-axis.", workingLatex: "-f(x)", explanation: "Reflection in the \\(x\\)-axis multiplies the output by \\(-1\\)." }, { stepNumber: 2, description: "Apply the vertical stretch by factor \\(3\\).", workingLatex: "3\\big(-f(x)\\big) = -3f(x)", explanation: "A vertical stretch multiplies the current output by \\(3\\)." }, { stepNumber: 3, description: "Apply the translation \\(\\binom{-4}{1}\\): replace \\(x\\) by \\(x+4\\) and add \\(1\\).", workingLatex: "g(x) = -3f(x + 4) + 1", explanation: "A translation of \\(-4\\) horizontally means \\(x \\to x+4\\) inside the function; the \\(+1\\) is the vertical shift. Doing the translation last matters because it must follow the stretch." }, { stepNumber: 4, description: "Transform the horizontal asymptote \\(y = 2\\) using the output operations.", workingLatex: "y = 2 \\xrightarrow{\\times(-1)} -2 \\xrightarrow{\\times 3} -6 \\xrightarrow{+1} -5", explanation: "A horizontal asymptote is a limiting \\(y\\)-value, so it is affected only by output transformations: reflect, stretch, then shift. The new horizontal asymptote is \\(y = -5\\)." }, { stepNumber: 5, description: "Transform the vertical asymptote \\(x = -1\\) using the input operation.", workingLatex: "x = -1 \\xrightarrow{\\text{shift }-4} x = -5", explanation: "A vertical asymptote is an \\(x\\)-value, so only the horizontal translation moves it. The reflection and vertical stretch leave it where it is. New vertical asymptote: \\(x = -5\\)." }, { stepNumber: 6, description: "Evaluate \\(g(-4)\\) using the point \\((0,5)\\) on \\(f\\).", workingLatex: "g(-4) = -3f(-4 + 4) + 1 = -3f(0) + 1 = -3(5) + 1 = -14", explanation: "At \\(x=-4\\) the argument \\(x+4\\) equals \\(0\\), and \\(f(0)=5\\) is given. Substituting yields \\(g(-4) = -14\\). The trick is recognising the translation lines \\(x=-4\\) up with the known point at \\(x=0\\)." } ], finalAnswer: "(a) \\(g(x) = -3f(x + 4) + 1\\). (b) Horizontal asymptote \\(y = -5\\); vertical asymptote \\(x = -5\\). (c) \\(g(-4) = -14\\)." } },
  { id: "y2fg6-116", topicRef: "y2fg6", topicTitle: "Combining Transformations 116", difficulty: "Standard", questionText: "\\(f\\) has vertical asymptote \\(x = 3\\). Asymptote of \\(y = f(2x)\\)?", marks: 2, examStyle: false, yearCreated: 2026, tags: ["asymptotes"], workedSolution: { steps: [ { stepNumber: 1, description: "Halve x.", workingLatex: "", explanation: "" } ], finalAnswer: "\\(x = \\tfrac{3}{2}\\)." } },
  { id: "y2fg6-117", topicRef: "y2fg6", topicTitle: "Combining Transformations 117", difficulty: "Foundation", questionText: "Apply: reflect in x-axis, stretch y ×4, shift left 2, shift up 3. Image of origin?", marks: 3, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply in order.", workingLatex: "(0, 0) \\to (0, 0) \\to (0, 0) \\to (-2, 0) \\to (-2, 3)", explanation: "" } ], finalAnswer: "\\((-2, 3)\\)." } },
  { id: "y2fg6-118", topicRef: "y2fg6", topicTitle: "Combining Transformations 118", difficulty: "Foundation", questionText: "Describe \\(y = 2(x - 1)^2 + 3\\) from \\(y = x^2\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "", explanation: "" } ], finalAnswer: "Right 1, stretch ×2, up 3." } },
  { id: "y2fg6-119", topicRef: "y2fg6", topicTitle: "Combining Transformations 119", difficulty: "Challenge", questionText: "A curve has equation \\(y = 2 - (3 - x)^3\\). (a) Show that this curve can be obtained from \\(y = x^3\\) by a sequence of transformations, describing each fully and in the correct order. (b) A student claims the curve is just \\(y = x^3\\) reflected in the point \\((3, 2)\\). By considering the image of a general point \\((3 + t,\\, t^3)\\), determine whether the student is correct. (c) State the coordinates of the point of inflection of \\(y = 2 - (3 - x)^3\\).", marks: 7, examStyle: true, yearCreated: 2026, tags: ["transformations", "order", "find-original", "image"], workedSolution: { steps: [ { stepNumber: 1, description: "Rewrite the argument so the \\(x\\)-coefficient is positive and factored.", workingLatex: "(3 - x)^3 = \\big(-(x - 3)\\big)^3 = -(x-3)^3", explanation: "Since the cube of \\(-1\\) is \\(-1\\), the reflection \\(3-x\\) can be pulled outside as an overall sign. Writing it this way exposes the genuine horizontal transformations." }, { stepNumber: 2, description: "Substitute back into the equation.", workingLatex: "y = 2 - \\big(-(x-3)^3\\big) = 2 + (x - 3)^3", explanation: "The two minus signs combine, so the equation simplifies to \\(y = (x-3)^3 + 2\\). This is the key simplification." }, { stepNumber: 3, description: "Describe the transformations from \\(y = x^3\\).", workingLatex: "x^3 \\to (x-3)^3 \\to (x-3)^3 + 2", explanation: "Replace \\(x\\) by \\(x-3\\): translation \\(3\\) right. Then add \\(2\\): translation \\(2\\) up. Equivalently a single translation by \\(\\binom{3}{2}\\). No reflection survives." }, { stepNumber: 4, description: "Test the student's claim. A reflection in the point \\((3,2)\\) sends \\((x,y)\\) to \\((6-x,\\,4-y)\\).", workingLatex: "(3 + t,\\, t^3) \\mapsto \\big(6 - (3+t),\\ 4 - t^3\\big) = (3 - t,\\ 4 - t^3)", explanation: "A point reflection in \\((3,2)\\) maps a point to the point an equal distance on the opposite side of \\((3,2)\\): the midpoint formula gives image \\((6-x, 4-y)\\)." }, { stepNumber: 5, description: "Check whether the image lies on \\(y = 2 + (x-3)^3\\).", workingLatex: "2 + \\big((3 - t) - 3\\big)^3 = 2 + (-t)^3 = 2 - t^3 \\neq 4 - t^3", explanation: "Substituting the image \\(x\\)-coordinate \\(3-t\\) gives a \\(y\\)-value of \\(2-t^3\\), but the reflected point has \\(y\\)-value \\(4-t^3\\). They differ by \\(2\\), so the student is wrong: the curve is a pure translation, not a point reflection." }, { stepNumber: 6, description: "Locate the point of inflection.", workingLatex: "y = (x - 3)^3 + 2 \\Rightarrow \\text{inflection at } (3, 2)", explanation: "The cubic \\(y=x^3\\) has its inflection at the origin; translating by \\(\\binom{3}{2}\\) moves it to \\((3,2)\\). Although \\((3,2)\\) is a centre of symmetry of the curve, the curve is not the image of \\(y=x^3\\) under reflection in that point — it is a translation, as part (b) showed." } ], finalAnswer: "(a) \\(y = 2 - (3-x)^3 = (x-3)^3 + 2\\): translate \\(y = x^3\\) by \\(\\binom{3}{2}\\) (3 right and 2 up); no reflection occurs. (b) The student is incorrect: reflecting \\((3+t,t^3)\\) in \\((3,2)\\) gives \\((3-t,\\,4-t^3)\\), but the curve passes through \\((3-t,\\,2-t^3)\\); the \\(y\\)-values differ by \\(2\\). (c) Point of inflection \\((3, 2)\\)." } },
  { id: "y2fg6-120", topicRef: "y2fg6", topicTitle: "Combining Transformations 120", difficulty: "Standard", questionText: "\\(y = f(x) = \\sqrt x\\) is shifted right 4 then stretched ×3 vertically. Equation?", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "", explanation: "" } ], finalAnswer: "\\(y = 3\\sqrt{x - 4}\\)." } },
  { id: "y2fg6-121", topicRef: "y2fg6", topicTitle: "Combining Transformations 121", difficulty: "Foundation", questionText: "Describe the transformations needed to go from \\(y = x^2\\) to each of: (a) \\(y = (x - 1)^2\\), (b) \\(y = x^2 + 3\\), (c) \\(y = 2x^2\\), (d) \\(y = -x^2\\).", marks: 4, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "", explanation: "" } ], finalAnswer: "(a) right 1; (b) up 3; (c) stretch ×2; (d) reflect in x-axis." } },
  { id: "y2fg6-122", topicRef: "y2fg6", topicTitle: "Combining Transformations 122", difficulty: "Standard", questionText: "Horizontal asymptote of \\(y = -e^x + 7\\)?", marks: 2, examStyle: false, yearCreated: 2026, tags: ["exp"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "", explanation: "" } ], finalAnswer: "\\(y = 7\\)." } },
  { id: "y2fg6-123", topicRef: "y2fg6", topicTitle: "Combining Transformations 123", difficulty: "Challenge", questionText: "The function \\(f\\) has roots at \\(x = -1\\) and \\(x = 3\\) only, a maximum point at \\((1, 8)\\), and \\(f(0) = 6\\). The curve \\(y = g(x)\\) is defined by \\(g(x) = 5 f\\big(\\tfrac{1}{2}x + 1\\big) - 10\\). (a) Find the roots of \\(y = g(x)\\). (b) Find the coordinates and nature of the turning point of \\(y = g(x)\\). (c) Determine the \\(y\\)-intercept of \\(y = g(x)\\).", marks: 7, examStyle: true, yearCreated: 2026, tags: ["transformations", "roots", "composite-argument", "image"], workedSolution: { steps: [ { stepNumber: 1, description: "Factorise the argument of \\(f\\).", workingLatex: "\\tfrac{1}{2}x + 1 = \\tfrac{1}{2}(x + 2)", explanation: "Factor out the \\(x\\)-coefficient \\(\\tfrac{1}{2}\\): this is a horizontal stretch of factor \\(2\\) followed by a translation \\(2\\) to the left. The argument must be factored before reading off shifts." }, { stepNumber: 2, description: "Find the roots: solve \\(\\tfrac{1}{2}x + 1 = r\\) for each root \\(r\\) of \\(f\\).", workingLatex: "\\tfrac{1}{2}x + 1 = r \\Rightarrow x = 2(r - 1) = 2r - 2", explanation: "The vertical stretch \\(\\times 5\\) and shift \\(-10\\) do not create or destroy roots only if the result is zero; check: \\(g=0 \\Rightarrow 5f(\\cdots)=10 \\Rightarrow f(\\cdots)=2\\), not \\(0\\). So roots of \\(g\\) occur where \\(f = 2\\), not where \\(f=0\\). We must reconsider." }, { stepNumber: 3, description: "Correct the root condition: solve \\(g(x) = 0\\).", workingLatex: "5f\\big(\\tfrac{1}{2}x+1\\big) - 10 = 0 \\Rightarrow f\\big(\\tfrac{1}{2}x+1\\big) = 2", explanation: "The vertical shift \\(-10\\) changes which \\(y\\)-value of \\(f\\) becomes a root. Roots of \\(g\\) need \\(f\\) to equal \\(2\\); the given roots of \\(f\\) (where \\(f=0\\)) are not directly the answer. We do not know every \\(x\\) with \\(f(x)=2\\), but the maximum value of \\(f\\) is \\(8\\), so such points do exist." }, { stepNumber: 4, description: "Locate the turning point. The maximum of \\(f\\) is at \\((1, 8)\\); transform the \\(x\\)-coordinate.", workingLatex: "\\tfrac{1}{2}x + 1 = 1 \\Rightarrow x = 0", explanation: "The argument equals \\(1\\) (the maximum's input) when \\(x = 0\\). The horizontal stretch by \\(2\\) and shift left \\(2\\) map the input \\(1\\) back to \\(x=0\\)." }, { stepNumber: 5, description: "Transform the \\(y\\)-coordinate \\(8\\) of the maximum.", workingLatex: "g = 5(8) - 10 = 30", explanation: "Apply the output operations: stretch \\(\\times 5\\) gives \\(40\\), then \\(-10\\) gives \\(30\\). Since the vertical stretch factor \\(5 > 0\\), a maximum stays a maximum. Turning point: \\((0, 30)\\), a maximum." }, { stepNumber: 6, description: "Find the \\(y\\)-intercept by setting \\(x = 0\\).", workingLatex: "g(0) = 5f\\big(\\tfrac{1}{2}(0)+1\\big) - 10 = 5f(1) - 10 = 5(8) - 10 = 30", explanation: "At \\(x=0\\) the argument is \\(1\\), and \\(f(1)=8\\) is the known maximum value. So the \\(y\\)-intercept coincides with the turning point at \\((0,30)\\); the value \\(f(0)=6\\) is a distractor not needed here." }, { stepNumber: 7, description: "Resolve part (a).", workingLatex: "g(x)=0 \\iff f\\big(\\tfrac{1}{2}x+1\\big)=2", explanation: "Because \\(f\\) is only specified at a few points, the exact roots of \\(g\\) cannot be pinned down: they are the \\(x\\)-values for which \\(f\\) takes the value \\(2\\), and \\(f=2\\) is reachable since \\(0 \\le 2 \\le 8\\). The correct, fully justified answer is the condition, not the original roots of \\(f\\)." } ], finalAnswer: "(a) The roots of \\(g\\) satisfy \\(f\\big(\\tfrac{1}{2}x+1\\big) = 2\\) (because the \\(-10\\) shift moves the zero level): they are not the images of the roots of \\(f\\) and cannot be found exactly from the given data. (b) Turning point \\((0, 30)\\), a maximum. (c) \\(y\\)-intercept \\(= g(0) = 30\\)." } },
  { id: "y2fg6-124", topicRef: "y2fg6", topicTitle: "Combining Transformations 124", difficulty: "Foundation", questionText: "If \\(f\\) has roots at \\(x = -1, 3\\), what are the roots of \\(y = f(\\tfrac{x}{2})\\)?", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Double.", workingLatex: "", explanation: "" } ], finalAnswer: "\\(x = -2, 6\\)." } },
  { id: "y2fg6-125", topicRef: "y2fg6", topicTitle: "Combining Transformations 125", difficulty: "Standard", questionText: "\\(f\\) has y-intercept 2 and x-intercept \\(-4\\). Find the y-intercept of \\(y = f(x + 3)\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Evaluate at \\(x = 0\\).", workingLatex: "f(0 + 3) = f(3)", explanation: "Not directly known." } ], finalAnswer: "\\(f(3)\\) — cannot be determined from the given info." } },
  { id: "y2fg6-126", topicRef: "y2fg6", topicTitle: "Combining Transformations 126", difficulty: "Challenge", questionText: "The function \\(f\\) satisfies \\(f(0) = 5\\), \\(f(2) = -3\\) and \\(f(-6) = 11\\). The curve \\(y = h(x)\\) is obtained from \\(y = f(x)\\) by a horizontal stretch of factor \\(\\tfrac{1}{2}\\), then a translation \\(3\\) units to the right, then a reflection in the \\(x\\)-axis, then a translation \\(4\\) units up. (a) Express \\(h(x)\\) in terms of \\(f\\). (b) Find the \\(y\\)-intercept of \\(y = h(x)\\). (c) Find \\(h(1)\\) and \\(h(4)\\), or explain why a value cannot be found.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["transformations", "order", "composite-argument", "image"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply the horizontal stretch of factor \\(\\tfrac{1}{2}\\).", workingLatex: "f(2x)", explanation: "A horizontal stretch of factor \\(\\tfrac{1}{2}\\) replaces \\(x\\) with \\(2x\\) (the reciprocal of the factor goes inside)." }, { stepNumber: 2, description: "Apply the translation \\(3\\) right.", workingLatex: "f\\big(2(x - 3)\\big) = f(2x - 6)", explanation: "Translating \\(3\\) right replaces \\(x\\) with \\(x-3\\); because the stretch is already in place, it becomes \\(2(x-3)\\). Doing the shift before the stretch would instead give \\(2x-3\\) — order matters." }, { stepNumber: 3, description: "Apply the reflection in the \\(x\\)-axis.", workingLatex: "-f(2x - 6)", explanation: "Reflection in the \\(x\\)-axis multiplies the output by \\(-1\\)." }, { stepNumber: 4, description: "Apply the translation \\(4\\) up.", workingLatex: "h(x) = -f(2x - 6) + 4", explanation: "Add \\(4\\) to the output. This is the final expression for \\(h\\)." }, { stepNumber: 5, description: "Find the \\(y\\)-intercept: set \\(x = 0\\).", workingLatex: "h(0) = -f(2(0) - 6) + 4 = -f(-6) + 4 = -(11) + 4 = -7", explanation: "The argument at \\(x=0\\) is \\(-6\\), and \\(f(-6)=11\\) is given. So the \\(y\\)-intercept is \\(-7\\). A common slip is to use \\(f(0)=5\\) directly, forgetting the argument is transformed." }, { stepNumber: 6, description: "Find \\(h(1)\\): evaluate the argument.", workingLatex: "h(1) = -f(2(1) - 6) + 4 = -f(-4) + 4", explanation: "The argument is \\(-4\\). We are not told \\(f(-4)\\), so \\(h(1)\\) cannot be evaluated from the given information." }, { stepNumber: 7, description: "Find \\(h(4)\\): evaluate the argument.", workingLatex: "h(4) = -f(2(4) - 6) + 4 = -f(2) + 4 = -(-3) + 4 = 7", explanation: "The argument is \\(2\\), and \\(f(2)=-3\\) is given, so \\(h(4) = 3 + 4 = 7\\). Recognising which \\(x\\)-values land on known inputs of \\(f\\) is the key skill." } ], finalAnswer: "(a) \\(h(x) = -f(2x - 6) + 4\\). (b) \\(y\\)-intercept \\(= h(0) = -7\\). (c) \\(h(4) = 7\\); \\(h(1) = -f(-4) + 4\\) cannot be evaluated because \\(f(-4)\\) is not given." } },
  { id: "y2fg6-127", topicRef: "y2fg6", topicTitle: "Combining Transformations 127", difficulty: "Challenge", questionText: "A curve is \\(y = x^2\\) reflected in the x-axis and shifted so its vertex is at \\((3, 7)\\). Write its equation.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "y = -(x - 3)^2 + 7", explanation: "" } ], finalAnswer: "\\(y = -(x - 3)^2 + 7\\)." } },
  { id: "y2fg6-128", topicRef: "y2fg6", topicTitle: "Combining Transformations 128", difficulty: "Standard", questionText: "Describe \\(y = \\sin(x - \\pi) + 2\\) from \\(y = \\sin x\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "", explanation: "" } ], finalAnswer: "Right \\(\\pi\\), up 2." } },
  { id: "y2fg6-129", topicRef: "y2fg6", topicTitle: "Combining Transformations 129", difficulty: "Standard", questionText: "Using \\(\\sin(x + \\pi) = -\\sin x\\), describe two equivalent ways to go from \\(y = \\sin x\\) to \\(y = \\sin(x + \\pi)\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "", explanation: "" } ], finalAnswer: "(a) Translate left \\(\\pi\\); (b) Reflect in x-axis." } },
  { id: "y2fg6-130", topicRef: "y2fg6", topicTitle: "Combining Transformations 130", difficulty: "Challenge", questionText: "Image of \\((4, 9)\\) on the transformed curve?", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Steps.", workingLatex: "(4, 9) \\to (8, 9) \\to (8, 3) \\to (8, 10)", explanation: "" } ], finalAnswer: "\\((8, 10)\\)." } },
  { id: "y2fg6-131", topicRef: "y2fg6", topicTitle: "Combining Transformations 131", difficulty: "Standard", questionText: "Describe the single transformation mapping \\(y = x^2\\) to \\(y = 4x^2\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "", explanation: "Also equivalent to horizontal stretch factor \\(\\tfrac{1}{2}\\)." } ], finalAnswer: "Vertical stretch scale factor 4 (or equivalently horizontal stretch ×\\(\\tfrac{1}{2}\\))." } },
  { id: "y2fg6-132", topicRef: "y2fg6", topicTitle: "Combining Transformations 132", difficulty: "Challenge", questionText: "(a) Show that the curve \\(y = -8(x - 1)^3 + 5\\) can be obtained from \\(y = x^3\\) by a sequence of transformations, describing each transformation fully and in order. (b) The same curve can be reached by first applying a horizontal transformation. Find a horizontal stretch factor \\(k\\) and a horizontal translation such that, followed by a vertical translation, they produce the identical curve, and explain why a reflection is not separately needed. (c) State the coordinates of the point on the curve corresponding to the point \\((2, 8)\\) on \\(y = x^3\\).", marks: 7, examStyle: true, yearCreated: 2026, tags: ["transformations", "order", "find-original", "image"], workedSolution: { steps: [ { stepNumber: 1, description: "Describe the standard route. Start with the horizontal translation.", workingLatex: "x^3 \\to (x - 1)^3", explanation: "Replacing \\(x\\) with \\(x-1\\) is a translation \\(1\\) unit to the right." }, { stepNumber: 2, description: "Apply the vertical scaling and reflection \\(\\times(-8)\\).", workingLatex: "(x - 1)^3 \\to -8(x - 1)^3", explanation: "Multiplying the output by \\(-8\\) is a vertical stretch of factor \\(8\\) combined with a reflection in the \\(x\\)-axis (the negative sign)." }, { stepNumber: 3, description: "Apply the vertical translation \\(+5\\).", workingLatex: "-8(x-1)^3 \\to -8(x - 1)^3 + 5", explanation: "Adding \\(5\\) shifts the curve up \\(5\\). This is the standard description: right \\(1\\), vertical stretch \\(\\times 8\\) with reflection in the \\(x\\)-axis, up \\(5\\)." }, { stepNumber: 4, description: "Find a purely horizontal scaling. Pull the factor \\(-8\\) inside the cube.", workingLatex: "-8(x-1)^3 = (-2)^3 (x-1)^3 = \\big(-2(x - 1)\\big)^3", explanation: "Because \\((-2)^3 = -8\\), the vertical stretch and reflection can be re-expressed as the inside factor \\(-2\\). This works only for an odd power like a cube." }, { stepNumber: 5, description: "Interpret the inside factor \\(-2\\).", workingLatex: "\\big(-2(x-1)\\big)^3 = \\big((-2x) + 2\\big)^3", explanation: "The inside factor \\(-2\\) is a horizontal stretch of factor \\(k = -\\tfrac{1}{2}\\) — i.e. a stretch of factor \\(\\tfrac{1}{2}\\) with a reflection in the \\(y\\)-axis. So the reflection is absorbed into the horizontal stretch, not needed separately." }, { stepNumber: 6, description: "Assemble the horizontal-first route.", workingLatex: "x^3 \\to \\big(-2(x - 1)\\big)^3 \\to \\big(-2(x-1)\\big)^3 + 5", explanation: "Apply a horizontal stretch of factor \\(-\\tfrac{1}{2}\\) about the line \\(x=1\\) (equivalently translate so the centre is at the origin, stretch, translate back), then translate up \\(5\\). No separate reflection is required because reflecting a cube in the \\(y\\)-axis equals reflecting it in the \\(x\\)-axis." }, { stepNumber: 7, description: "Transform the point \\((2, 8)\\).", workingLatex: "x: \\ 2 \\xrightarrow{\\text{right }1} 3; \\qquad y: \\ 8 \\xrightarrow{\\times(-8)} -64 \\xrightarrow{+5} -59", explanation: "Use the standard route from part (a): the \\(x\\)-coordinate \\(2\\) shifts right \\(1\\) to \\(3\\); the \\(y\\)-coordinate \\(8\\) is multiplied by \\(-8\\) then increased by \\(5\\). Image point: \\((3, -59)\\)." } ], finalAnswer: "(a) Translate \\(y=x^3\\) by \\(1\\) right, then vertical stretch factor \\(8\\) with reflection in the \\(x\\)-axis, then translate \\(5\\) up: \\(y = -8(x-1)^3 + 5\\). (b) Since \\(-8(x-1)^3 = \\big(-2(x-1)\\big)^3\\), a horizontal stretch of factor \\(k = -\\tfrac{1}{2}\\) about \\(x = 1\\) followed by a translation \\(5\\) up gives the same curve; the \\(y\\)-axis reflection inside the cube reproduces the \\(x\\)-axis reflection, so no separate reflection is needed. (c) Image of \\((2,8)\\) is \\((3, -59)\\)." } },
  { id: "y2fg6-133", topicRef: "y2fg6", topicTitle: "Combining Transformations 133", difficulty: "Standard", questionText: "\\(y = x^3\\) passes through \\((2, 8)\\). Image on \\(y = (x - 1)^3 + 2\\)?", marks: 2, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "Apply.", workingLatex: "(2, 8) \\to (3, 8) \\to (3, 10)", explanation: "" } ], finalAnswer: "\\((3, 10)\\)." } },
  { id: "y2fg6-134", topicRef: "y2fg6", topicTitle: "Combining Transformations 134", difficulty: "Standard", questionText: "\\(y = x^3\\) has inflection at origin. Inflection of \\(y = (x + 5)^3 - 4\\)?", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "(0, 0) \\to (-5, 0) \\to (-5, -4)", explanation: "" } ], finalAnswer: "\\((-5, -4)\\)." } },
  { id: "y2fg6-135", topicRef: "y2fg6", topicTitle: "Combining Transformations 135", difficulty: "Challenge", questionText: "A parabola \\(C\\) is the image of \\(y = x^2\\) under an unknown combination of one vertical stretch (factor \\(a > 0\\)) and one translation by \\(\\binom{p}{q}\\). It is known that \\(C\\) passes through the points \\((1, 5)\\), \\((3, 5)\\) and \\((2, 1)\\). (a) Use the symmetry of the two equal \\(y\\)-values to find the horizontal translation \\(p\\). (b) Hence find the vertical stretch factor \\(a\\) and the vertical translation \\(q\\), and write the equation of \\(C\\) in the form \\(y = a(x - p)^2 + q\\). (c) State the single transformation that maps \\(C\\) back onto \\(y = x^2\\) if the translation is undone first.", marks: 7, examStyle: true, yearCreated: 2026, tags: ["transformations", "find-original", "image", "order"], workedSolution: { steps: [ { stepNumber: 1, description: "Use the two points with equal \\(y\\)-values to locate the axis of symmetry.", workingLatex: "x = \\tfrac{1 + 3}{2} = 2", explanation: "On a parabola, two points at the same height are equidistant from the axis of symmetry. The axis is the average of their \\(x\\)-coordinates: \\(x=2\\). A parabola is symmetric about its vertex." }, { stepNumber: 2, description: "Identify the horizontal translation \\(p\\).", workingLatex: "x = p \\Rightarrow p = 2", explanation: "After translating \\(y=x^2\\) (axis \\(x=0\\)) by \\(\\binom{p}{q}\\), the axis moves to \\(x=p\\). Since the axis is \\(x=2\\), we get \\(p=2\\)." }, { stepNumber: 3, description: "The point \\((2,1)\\) lies on the axis, so it is the vertex; this gives \\(q\\).", workingLatex: "y = a(x - 2)^2 + q, \\quad (2, 1): \\ 1 = a(0) + q \\Rightarrow q = 1", explanation: "At \\(x=2\\) the squared term vanishes, leaving \\(y=q\\). Since the curve passes through \\((2,1)\\), the vertex is \\((2,1)\\) and \\(q=1\\)." }, { stepNumber: 4, description: "Use \\((1,5)\\) to find the stretch factor \\(a\\).", workingLatex: "5 = a(1 - 2)^2 + 1 = a(1) + 1", explanation: "Substitute a non-vertex point into \\(y=a(x-2)^2+1\\). The factor \\(a\\) is the only unknown left." }, { stepNumber: 5, description: "Solve for \\(a\\).", workingLatex: "5 = a + 1 \\Rightarrow a = 4", explanation: "So the vertical stretch factor is \\(4\\). Check with \\((3,5)\\): \\(4(3-2)^2+1 = 4+1 = 5\\) — consistent, confirming the answer." }, { stepNumber: 6, description: "Write the equation of \\(C\\).", workingLatex: "y = 4(x - 2)^2 + 1", explanation: "This is \\(y=x^2\\) stretched vertically by factor \\(4\\) and translated by \\(\\binom{2}{1}\\)." }, { stepNumber: 7, description: "Describe the inverse transformation onto \\(y = x^2\\).", workingLatex: "y = 4(x-2)^2 + 1 \\xrightarrow{\\text{translate }\\binom{-2}{-1}} y = 4x^2 \\xrightarrow{\\ ?\\ } y = x^2", explanation: "Undo the translation first by shifting \\(\\binom{-2}{-1}\\), reaching \\(y=4x^2\\). The remaining single transformation is a vertical stretch of factor \\(\\tfrac{1}{4}\\) (the reciprocal of \\(a\\)), which compresses \\(y=4x^2\\) back to \\(y=x^2\\)." } ], finalAnswer: "(a) Axis of symmetry \\(x = 2\\), so \\(p = 2\\). (b) Vertex \\((2,1)\\) gives \\(q = 1\\); substituting \\((1,5)\\) gives \\(a = 4\\); \\(C\\) is \\(y = 4(x - 2)^2 + 1\\). (c) After translating by \\(\\binom{-2}{-1}\\) to reach \\(y = 4x^2\\), the single transformation back to \\(y = x^2\\) is a vertical stretch of factor \\(\\tfrac{1}{4}\\)." } },
  { id: "y2fg6-136", topicRef: "y2fg6", topicTitle: "Combining Transformations 136", difficulty: "Challenge", questionText: "Describe a sequence of transformations that maps \\(y = \\sin x\\) to \\(y = \\cos 2x\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "\\(\\cos 2x = \\sin(2x + \\tfrac{\\pi}{2}) = \\sin(2(x + \\tfrac{\\pi}{4}))\\).", workingLatex: "", explanation: "" } ], finalAnswer: "Left \\(\\tfrac{\\pi}{4}\\), horizontal stretch ×\\(\\tfrac{1}{2}\\)." } },
  { id: "y2fg6-137", topicRef: "y2fg6", topicTitle: "Combining Transformations 137", difficulty: "Standard", questionText: "Simplify \\(y = -\\cos(x + \\pi)\\) in terms of \\(\\cos x\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["trig"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "-\\cos(x + \\pi) = -(-\\cos x) = \\cos x", explanation: "" } ], finalAnswer: "\\(y = \\cos x\\) (no net change)." } },
  { id: "y2fg6-138", topicRef: "y2fg6", topicTitle: "Combining Transformations 138", difficulty: "Standard", questionText: "Apply to \\(y = f(x)\\): up 2, then stretch y ×3. Find \\(y\\)-value when \\(f(x) = 4\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "3(4 + 2) = 18", explanation: "" } ], finalAnswer: "18." } },
  { id: "y2fg6-139", topicRef: "y2fg6", topicTitle: "Combining Transformations 139", difficulty: "Standard", questionText: "Apply to \\(y = f(x)\\): stretch y ×3, then up 2. \\(y\\)-value when \\(f(x) = 4\\)?", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "3 \\cdot 4 + 2 = 14", explanation: "" } ], finalAnswer: "14 (order matters)." } },
  { id: "y2fg6-140", topicRef: "y2fg6", topicTitle: "Combining Transformations 140", difficulty: "Challenge", questionText: "Show that two successive reflections in the y-axis give the identity.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "", workingLatex: "f(-(-x)) = f(x)", explanation: "" } ], finalAnswer: "Identity. \\(\\blacksquare\\)" } },
  { id: "y2fg6-141", topicRef: "y2fg6", topicTitle: "Combining Transformations 141", difficulty: "Challenge", questionText: "Apply to \\(y = f(x)\\): translate right 3, then reflect in y-axis. Write the resulting equation.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["transformations"], workedSolution: { steps: [ { stepNumber: 1, description: "After shift: \\(y = f(x - 3)\\).", workingLatex: "", explanation: "Now reflect in y-axis." } ], finalAnswer: "\\(y = f(-x - 3)\\)." } },
];
